function portalHref(path = ''): string {
  const basePath = portalData?.projectBasePath || window.location.pathname || '/'
  return `${basePath.replace(/\/?$/, '/')}${path.replace(/^\/+/, '')}`
}

function portalViewHref(view: PortalRouteKey): string {
  return portalHref(`?portal_view=${encodeURIComponent(view)}`)
}

function readPortalView(): PortalRouteKey {
  const payloadView = portalData?.portalView
  if (payloadView === 'bed-management') return 'bed-management'
  if (payloadView === 'signin') return 'signin'

  if (typeof window !== 'undefined') {
    const requestedView = new URLSearchParams(window.location.search).get('portal_view')
    if (requestedView === 'bed-management') return 'bed-management'
    if (requestedView === 'signin') return 'signin'
  }

  return 'dashboard'
}

function AiRephraseCard() {
  const rephraseStorageKey = `builderx:ai-rephrase:${phaseField(portalData?.currentUser, 'user_key', 'guest')}`
  const [text, setText] = React.useState('')
  const [taskId, setTaskId] = React.useState(() => {
    try { return sessionStorage.getItem(rephraseStorageKey) || '' } catch { return '' }
  })
  const [status, setStatus] = React.useState('idle')
  const [message, setMessage] = React.useState('')
  const [rewrittenText, setRewrittenText] = React.useState('')

  const busy = taskId !== ''

  React.useEffect(() => {
    try {
      if (taskId) sessionStorage.setItem(rephraseStorageKey, taskId)
      else sessionStorage.removeItem(rephraseStorageKey)
    } catch {
      // A blocked sessionStorage must not prevent task polling.
    }
  }, [rephraseStorageKey, taskId])

  React.useEffect(() => {
    if (!taskId) return

    let cancelled = false
    let timer: number | null = null

    const poll = async () => {
      try {
        const response = await fetch(portalHref(`?action=ai_task_status&task_id=${encodeURIComponent(taskId)}`), { cache: 'no-store' })
        const result = await response.json() as { ok?: boolean; message?: string; data?: { task?: Record<string, any> } }
        if (!response.ok || result.ok !== true || !result.data?.task) {
          throw new Error(result.message || 'The AI task status could not be read.')
        }

        const task = result.data.task
        const nextStatus = String(task.status || 'queued')
        if (cancelled) return
        setStatus(nextStatus)
        if (nextStatus === 'completed') {
          setRewrittenText(String(task.output?.rewritten_text || ''))
          setMessage('Rephrase complete. The result was saved before this component updated.')
          setTaskId('')
          return
        }
        if (['failed', 'cancelled'].includes(nextStatus)) {
          setMessage(String(task.error?.message || 'The AI task did not complete.'))
          setTaskId('')
          return
        }
        setMessage(nextStatus === 'running' ? 'VS Code Codex Chat is processing the rephrase…' : 'The task is queued for VS Code Codex Chat…')
        timer = window.setTimeout(() => void poll(), 1500)
      } catch (error) {
        if (cancelled) return
        setMessage(error instanceof Error ? error.message : 'The AI task status could not be read.')
        setStatus('failed')
        setTaskId('')
      }
    }

    void poll()
    return () => {
      cancelled = true
      if (timer !== null) window.clearTimeout(timer)
    }
  }, [taskId])

  const submit = async () => {
    const value = text.trim()
    if (!value || busy) return
    setStatus('queued')
    setMessage('Creating a tracked rephrase task…')
    setRewrittenText('')

    const formData = new FormData()
    formData.set('csrf', portalData?.csrf || '')
    formData.set('action', 'create_ai_task')
    formData.set('text', value)

    try {
      const response = await fetch(portalHref(''), {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json() as { ok?: boolean; message?: string; data?: { task_id?: string; status?: string } }
      if (!response.ok || result.ok !== true || !result.data?.task_id) {
        throw new Error(result.message || 'The AI task could not be queued.')
      }
      setTaskId(String(result.data.task_id))
      setStatus(String(result.data.status || 'queued'))
    } catch (error) {
      setStatus('failed')
      setMessage(error instanceof Error ? error.message : 'The AI task could not be queued.')
    }
  }

  return (
    <Card className="border-primary/30 bg-primary/5">
      <CardHeader className="border-b pb-3">
        <CardTitle className="flex items-center gap-2 text-base"><Sparkles className="size-4" />AI Rephrase Assistant</CardTitle>
        <CardDescription>Correct spelling and grammar through a tracked Coordinator task. The page updates this result only.</CardDescription>
      </CardHeader>
      <CardContent className="grid gap-3 pt-4">
        <Textarea value={text} onChange={(event) => setText(event.target.value)} placeholder="Type a sentence to rephrase…" maxLength={50000} disabled={busy} aria-label="Sentence to rephrase" />
        <div className="flex flex-wrap items-center gap-2">
          <Button type="button" onClick={() => void submit()} disabled={busy || !text.trim()}>{busy ? <LoaderCircle className="animate-spin" /> : <Sparkles />} {busy ? 'Processing…' : 'Rephrase sentence'}</Button>
          <Badge variant="outline">{status === 'idle' ? 'Ready' : status}</Badge>
        </div>
        <p aria-live="polite" className="min-h-5 text-sm text-muted-foreground">{message}</p>
        {rewrittenText ? <div className="rounded-md bg-muted/20 p-3"><p className="text-xs font-medium text-muted-foreground">Corrected result</p><p className="mt-1 whitespace-pre-wrap text-sm">{rewrittenText}</p></div> : null}
      </CardContent>
    </Card>
  )
}

function CoordinatorManagementCard() {
  const [specialists, setSpecialists] = React.useState<Array<Record<string, any>>>([])
  const [memories, setMemories] = React.useState<Array<Record<string, any>>>([])
  const [message, setMessage] = React.useState('')
  const [busy, setBusy] = React.useState(false)

  const load = React.useCallback(async () => {
    const response = await fetch(portalHref('?action=ai_specialists'), { cache: 'no-store' })
    const result = await response.json() as { ok?: boolean; data?: { specialists?: Array<Record<string, any>>; memories?: Array<Record<string, any>> }; message?: string }
    if (!response.ok || result.ok !== true) throw new Error(result.message || 'The Coordinator directory could not be loaded.')
    setSpecialists(Array.isArray(result.data?.specialists) ? result.data.specialists : [])
    setMemories(Array.isArray(result.data?.memories) ? result.data.memories : [])
  }, [])

  React.useEffect(() => {
    if (portalData?.isAdmin) void load().catch((error) => setMessage(error instanceof Error ? error.message : 'The directory could not be loaded.'))
  }, [load])

  if (!portalData?.isAdmin) return null

  const submit = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    const formElement = event.currentTarget
    setBusy(true)
    setMessage('Saving Coordinator proposal…')
    const formData = new FormData(formElement)
    formData.set('csrf', portalData?.csrf || '')
    try {
      const response = await fetch(portalHref(''), { method: 'POST', body: formData, headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' } })
      const result = await response.json() as { ok?: boolean; message?: string }
      if (!response.ok || result.ok !== true) throw new Error(result.message || 'The Coordinator proposal could not be saved.')
      formElement.reset()
      setMessage('Saved as pending approval.')
      await load()
    } catch (error) {
      setMessage(error instanceof Error ? error.message : 'The Coordinator proposal could not be saved.')
    } finally {
      setBusy(false)
    }
  }

  const approve = async (action: 'approve_specialist' | 'approve_memory', key: string, field: string) => {
    setBusy(true)
    const formData = new FormData()
    formData.set('csrf', portalData?.csrf || '')
    formData.set('action', action)
    formData.set(field, key)
    try {
      const response = await fetch(portalHref(''), { method: 'POST', body: formData, headers: { Accept: 'application/json', 'X-Requested-With': 'XMLHttpRequest' } })
      const result = await response.json() as { ok?: boolean; message?: string }
      if (!response.ok || result.ok !== true) throw new Error(result.message || 'Approval could not be completed.')
      setMessage('Approved and available to the Coordinator.')
      await load()
    } catch (error) {
      setMessage(error instanceof Error ? error.message : 'Approval could not be completed.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <Card>
      <CardHeader className="border-b pb-3"><CardTitle className="flex items-center gap-2 text-base"><Workflow className="size-4" />Coordinator &amp; Specialist Directory</CardTitle><CardDescription>Review specialists and submit approved UI/UX or project rules to AI-Memory and Obsidian.</CardDescription></CardHeader>
      <CardContent className="grid gap-5 pt-4">
        <div className="grid gap-2"><p className="text-sm font-medium">Registered specialists</p>{specialists.length === 0 ? <p className="text-sm text-muted-foreground">No specialists registered yet.</p> : specialists.map((specialist) => <div key={String(specialist.specialist_key)} className="flex flex-wrap items-center gap-2 rounded-md bg-muted/20 p-3"><div className="min-w-0 flex-1"><p className="font-medium">{String(specialist.name || specialist.specialist_key)}</p><p className="text-xs text-muted-foreground">{String(specialist.status)} · {Array.isArray(specialist.stages) ? specialist.stages.join(', ') : ''} · {Array.isArray(specialist.skills) ? specialist.skills.join(', ') : 'no skills'}</p></div>{specialist.status === 'pending_approval' ? <Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => void approve('approve_specialist', String(specialist.specialist_key), 'specialist_key')}>Approve</Button> : null}</div>)}</div>
        <form className="grid gap-3 rounded-md bg-muted/20 p-3" onSubmit={(event) => { const form = event.currentTarget; form.querySelector<HTMLInputElement>('[name="action"]')!.value = 'propose_specialist'; void submit(event) }}><input type="hidden" name="action" value="propose_specialist" /><p className="text-sm font-medium">Register an on-demand specialist</p><div className="grid gap-3 sm:grid-cols-2"><Input name="specialist_key" placeholder="specialist_key" required /><Input name="specialist_name" placeholder="Specialist name" required /></div><Input name="specialist_purpose" placeholder="Purpose" required /><Input name="specialist_stages" defaultValue="Validate" placeholder="Stages, comma separated" required /><Input name="specialist_skills" placeholder="Skills, comma separated" required /><div className="grid gap-3 sm:grid-cols-2"><Input name="specialist_tools" defaultValue="read_files" placeholder="Allowed tools" required /><select name="specialist_write_scope" className="h-10 rounded-md border bg-background px-3 text-sm"><option value="none">No writes</option><option value="communication_only">Communication only</option><option value="phase_manager_approval">Phase Manager approval</option></select></div><label className="flex items-center gap-2 text-xs"><input type="checkbox" name="specialist_temporary" /> Temporary specialist</label><Button type="submit" disabled={busy}>Submit specialist proposal</Button></form>
        <form className="grid gap-3 rounded-md bg-muted/20 p-3" onSubmit={(event) => { const form = event.currentTarget; form.querySelector<HTMLInputElement>('[name="action"]')!.value = 'propose_memory'; void submit(event) }}><input type="hidden" name="action" value="propose_memory" /><p className="text-sm font-medium">Coordinator Memory Chat</p><p className="text-xs text-muted-foreground">Example: “Standard buttons must be square across the project.” This creates a pending rule for approval.</p><Input name="memory_title" placeholder="Memory title" required /><Input name="memory_tags" defaultValue="brand,ui-ux" placeholder="Tags, comma separated" required /><Textarea name="memory_content" placeholder="Coordinator instruction or approved rule…" required /><Button type="submit" disabled={busy}>Save memory proposal</Button></form>
        <div className="grid gap-2"><p className="text-sm font-medium">Recent AI-Memory</p>{memories.slice(0, 6).map((memory) => <div key={String(memory.memory_id)} className="flex flex-wrap items-center gap-2 rounded-md bg-muted/20 p-3"><div className="min-w-0 flex-1"><p className="font-medium">{String(memory.title)}</p><p className="text-xs text-muted-foreground">{String(memory.status)} · {String(memory.memory_type)} · {Array.isArray(memory.tags) ? memory.tags.join(', ') : ''}</p></div>{memory.status === 'pending_approval' ? <Button type="button" size="sm" variant="outline" disabled={busy} onClick={() => void approve('approve_memory', String(memory.memory_id), 'memory_id')}>Approve</Button> : null}</div>)}</div>
        <p aria-live="polite" className="min-h-5 text-xs text-muted-foreground">{message}</p>
      </CardContent>
    </Card>
  )
}

function readStoredPortalTheme(): AdminThemeMode {
  if (typeof window === 'undefined') return 'light'

  const projectKey = portalData?.projectBasePath || window.location.pathname || '/'
  const userKey = phaseField(portalData?.currentUser, 'user_key', 'guest')
  const key = `builderx:theme:${encodeURIComponent(projectKey)}:${encodeURIComponent('user-portal')}:${encodeURIComponent(userKey)}`
  return window.localStorage.getItem(key) === 'dark' ? 'dark' : 'light'
}

function writeStoredPortalTheme(theme: AdminThemeMode): void {
  if (typeof window === 'undefined') return

  const projectKey = portalData?.projectBasePath || window.location.pathname || '/'
  const userKey = phaseField(portalData?.currentUser, 'user_key', 'guest')
  const key = `builderx:theme:${encodeURIComponent(projectKey)}:${encodeURIComponent('user-portal')}:${encodeURIComponent(userKey)}`
  window.localStorage.setItem(key, theme)
}

type PortalViewKey = PortalRouteKey | 'signin'
const portalSidebarMobileCookieName = 'portal_sidebar_mobile_state'

const portalSidebarSections = [
  { key: 'dashboard', label: 'Dashboard', href: '?portal_view=dashboard', icon: LayoutDashboard },
  { key: 'bed-management', label: 'Bed Management', href: '?portal_view=bed-management', icon: BedDouble },
]

function PortalFlashMessage() {
  return <SubmissionFeedback flash={portalData?.flash || null} />
}

function PortalSidebarMobilePersistence() {
  const { isMobile, openMobile, setOpenMobile } = useSidebar()
  const [mobileRestored, setMobileRestored] = React.useState(false)

  React.useEffect(() => {
    if (!isMobile) {
      setMobileRestored(false)
      return
    }

    setOpenMobile(readBooleanCookie(portalSidebarMobileCookieName) ?? false)
    setMobileRestored(true)
  }, [isMobile, setOpenMobile])

  React.useEffect(() => {
    if (!isMobile || !mobileRestored) return

    writeBooleanCookie(portalSidebarMobileCookieName, openMobile)
  }, [isMobile, mobileRestored, openMobile])

  return null
}

function PortalShell({
  children,
  activeView,
  title,
  breadcrumbItems,
  buildTarget,
  footerLabel,
  theme,
  onThemeToggle,
}: {
  children: React.ReactNode
  activeView: PortalViewKey
  title: string
  breadcrumbItems: string[]
  buildTarget: string
  footerLabel: string
  theme: AdminThemeMode
  onThemeToggle: () => void
}) {
  const nextThemeLabel = theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'
  const { loading: portalNetworkLoading } = useShellNetworkLoading()
  const portalSignedIn = Boolean(portalData?.currentUser?.user_key)
  const [messengerOpen, setMessengerOpen] = usePersistentMessengerOpen(portalSignedIn)
  const [messengerNotificationSoundKey, setMessengerNotificationSoundKey] = React.useState(() => normalizePortalTaskNotificationSoundKey(portalData?.currentUser?.messenger_notification_sound || defaultPortalMessengerNotificationSoundKey))
  const [messengerNotificationVolumeKey, setMessengerNotificationVolumeKey] = React.useState(() => normalizePortalTaskNotificationVolumeKey(portalData?.currentUser?.messenger_notification_volume || defaultPortalMessengerNotificationVolumeKey))
  const [taskNotificationSoundKey, setTaskNotificationSoundKey] = React.useState(() => normalizePortalTaskNotificationSoundKey(portalData?.currentUser?.task_notification_sound))
  const [taskNotificationVolumeKey, setTaskNotificationVolumeKey] = React.useState(() => normalizePortalTaskNotificationVolumeKey(portalData?.currentUser?.task_notification_volume))
  const [taskSoundSettingsOpen, setTaskSoundSettingsOpen] = React.useState(false)
  const { unreadCount, clearUnread } = useMessengerNotifications(messengerOpen, portalSignedIn, messengerNotificationSoundKey, messengerNotificationVolumeKey)
  const { updateCount, clearUpdates } = usePortalTaskUpdates(portalSignedIn, taskNotificationSoundKey, taskNotificationVolumeKey)
  const defaultSidebarOpen = React.useMemo(
    () => readBooleanCookie(sidebarCookieName) ?? true,
    [],
  )
  const openMessenger = React.useCallback(() => {
    if (!portalSignedIn) {
      setMessengerOpen(false)
      window.location.assign(portalHref('#portal-login'))
      return
    }
    clearUnread()
    setMessengerOpen(true)
  }, [clearUnread, portalSignedIn, setMessengerOpen])
  const openTaskSoundSettings = React.useCallback(() => {
    if (!portalSignedIn) {
      window.location.assign(portalHref('#portal-login'))
      return
    }
    setTaskSoundSettingsOpen(true)
  }, [portalSignedIn])
  const handleNotificationSoundsSaved = React.useCallback((savedTaskSoundKey: string, savedTaskVolumeKey: string, savedMessengerSoundKey: string, savedMessengerVolumeKey: string) => {
    const normalizedTaskSoundKey = normalizePortalTaskNotificationSoundKey(savedTaskSoundKey)
    const normalizedTaskVolumeKey = normalizePortalTaskNotificationVolumeKey(savedTaskVolumeKey)
    const normalizedMessengerSoundKey = normalizePortalTaskNotificationSoundKey(savedMessengerSoundKey)
    const normalizedMessengerVolumeKey = normalizePortalTaskNotificationVolumeKey(savedMessengerVolumeKey)
    setTaskNotificationSoundKey(normalizedTaskSoundKey)
    setTaskNotificationVolumeKey(normalizedTaskVolumeKey)
    setMessengerNotificationSoundKey(normalizedMessengerSoundKey)
    setMessengerNotificationVolumeKey(normalizedMessengerVolumeKey)
    if (portalData?.currentUser) {
      portalData.currentUser.task_notification_sound = normalizedTaskSoundKey
      portalData.currentUser.task_notification_volume = normalizedTaskVolumeKey
      portalData.currentUser.messenger_notification_sound = normalizedMessengerSoundKey
      portalData.currentUser.messenger_notification_volume = normalizedMessengerVolumeKey
    }
  }, [])
  const displayTitle = messengerOpen ? 'Messenger' : title
  const displayBreadcrumbItems = messengerOpen ? [...breadcrumbItems.slice(0, 1), 'Messenger'] : breadcrumbItems

  return (
    <TooltipProvider>
      <SidebarProvider
        defaultOpen={defaultSidebarOpen}
        className="h-svh min-h-0 w-full overflow-hidden"
        style={{
          '--sidebar-width': '256px',
        } as React.CSSProperties}
      >
        <PortalSidebarMobilePersistence />
        <PortalSidebar activeView={activeView} theme={theme} onThemeToggle={onThemeToggle} onNavigate={() => setMessengerOpen(false)} />
        <SidebarInset className="h-svh max-h-svh min-h-0 overflow-hidden">
          <header className="sticky top-0 z-20 flex h-14 shrink-0 items-center justify-between gap-3 border-b bg-background px-4 transition-[width,height] ease-linear group-has-data-[collapsible=icon]/sidebar-wrapper:h-12">
            <div className="flex min-w-0 items-center gap-3">
              <SidebarTrigger className="-ml-1" />
              <Separator orientation="vertical" className="data-vertical:h-6 data-vertical:self-center" />
              <div className="min-w-0">
                <h1 className="truncate text-sm font-semibold tracking-normal">{displayTitle}</h1>
                <ShadcnBreadcrumb>
                  <BreadcrumbList>
                    {displayBreadcrumbItems.map((item, index) => (
                      <React.Fragment key={`${item}-${index}`}>
                        {index > 0 && <BreadcrumbSeparator />}
                        <BreadcrumbItem>
                          <BreadcrumbPage>{item}</BreadcrumbPage>
                        </BreadcrumbItem>
                      </React.Fragment>
                    ))}
                  </BreadcrumbList>
                </ShadcnBreadcrumb>
              </div>
            </div>
            <nav className="ml-auto flex min-w-0 items-center justify-end gap-2" aria-label="Portal controls">
              <MessengerHeaderButton onOpen={openMessenger} unreadCount={unreadCount} />
              <PortalTaskUpdateHeaderButton onOpen={clearUpdates} updateCount={updateCount} />
              <Tooltip>
                <TooltipTrigger
                  render={<Button type="button" variant="outline" size="icon-sm" aria-label="Notification sound settings" title="Notification Sound Settings" onClick={openTaskSoundSettings} />}
                >
                  <Music2 />
                </TooltipTrigger>
                <TooltipContent>Notification Sound Settings</TooltipContent>
              </Tooltip>
              <HeaderControlSeparator />
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button type="button" variant="outline" size="icon-sm" aria-label={nextThemeLabel} onClick={onThemeToggle} />
                  }
                >
                  {theme === 'dark' ? <Sun /> : <Moon />}
                </TooltipTrigger>
                <TooltipContent>{nextThemeLabel}</TooltipContent>
              </Tooltip>
            </nav>
          </header>
          <SampleShellProgressBar active={portalNetworkLoading} />

          <main className={cn('flex min-h-0 w-full flex-1 flex-col gap-4 p-4', messengerOpen ? 'overflow-hidden' : 'overflow-y-auto pb-16')}>
            {messengerOpen ? <MessengerWorkspace onClose={() => setMessengerOpen(false)} /> : <><PortalFlashMessage />{children}</>}
          </main>

          <footer className="sticky bottom-0 z-20 grid min-h-12 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-3 border-t bg-background px-4 text-xs text-muted-foreground">
            <span className="min-w-0 truncate">{footerLabel}</span>
            <SampleFooterLoadingIndicator active={portalNetworkLoading} />
            <span className="min-w-0 justify-self-end truncate text-right">Mode: Preview · Build Target {buildTarget}</span>
          </footer>
        </SidebarInset>
      </SidebarProvider>
      <PortalNotificationSoundSettingsDialog
        open={taskSoundSettingsOpen}
        onOpenChange={setTaskSoundSettingsOpen}
        taskSoundKey={taskNotificationSoundKey}
        taskVolumeKey={taskNotificationVolumeKey}
        messengerSoundKey={messengerNotificationSoundKey}
        messengerVolumeKey={messengerNotificationVolumeKey}
        onSaved={handleNotificationSoundsSaved}
      />
    </TooltipProvider>
  )
}

