function aiJobFromResult(result: any): AiJobPayload | null {
  const job = result?.data?.ai_job
  if (!job || typeof job !== 'object') return null

  return {
    id: String(job.id || ''),
    status: String(job.status || 'queued'),
    action: String(job.action || ''),
    label: String(job.label || 'AI Processing'),
    message: String(job.message || 'AI is currently processing.'),
    segment_index: Number(job.segment_index || 0),
    segment_total: Number(job.segment_total || 0),
    segment_label: String(job.segment_label || ''),
    prompt: String(job.prompt || ''),
    context: job.context && typeof job.context === 'object' ? job.context : {},
    memory: job.memory && typeof job.memory === 'object' ? job.memory : {},
    memory_scope_id: String(job.memory_scope_id || ''),
    token_usage: job.token_usage && typeof job.token_usage === 'object' ? job.token_usage : {},
    provenance: job.provenance && typeof job.provenance === 'object' ? job.provenance : {},
    checkpoints: Array.isArray(job.checkpoints) ? job.checkpoints : [],
    rollback: job.rollback && typeof job.rollback === 'object' ? job.rollback : {},
    result: job.result && typeof job.result === 'object' ? job.result : null,
    error: String(job.error || ''),
    created_at: String(job.created_at || ''),
    updated_at: String(job.updated_at || ''),
  }
}

function emitAiJobUpdate(job: AiJobPayload): void {
  if (job.id === '' || typeof window === 'undefined') return
  window.dispatchEvent(new CustomEvent(aiJobUpdatedEvent, { detail: job }))
}

function maybeHandleAiBackgroundJobResult(result: any): boolean {
  const job = aiJobFromResult(result)
  if (!job) return false
  emitAiJobUpdate(job)
  return true
}

