type PendingFormSubmission = {
  form: HTMLFormElement
  submitter: HTMLElement | null
  title: string
  description: string
}

function formActionLabel(form: HTMLFormElement, submitter: HTMLElement | null): string {
  const submitterLabel = submitter?.textContent?.replace(/\s+/g, ' ').trim()
  if (submitterLabel) return submitterLabel

  const action = form.elements.namedItem('action')
  if (action instanceof HTMLInputElement && action.value.trim()) return action.value.trim().replace(/[_-]+/g, ' ')
  return 'submit this form'
}

function FormConfirmationGuard({ children }: { children: React.ReactNode }) {
  const [pending, setPending] = React.useState<PendingFormSubmission | null>(null)
  const bypassFormsRef = React.useRef<Set<HTMLFormElement>>(new Set())
  const confirmingRef = React.useRef(false)

  React.useEffect(() => {
    function handleDocumentSubmit(nativeEvent: Event) {
      const form = nativeEvent.target instanceof HTMLFormElement ? nativeEvent.target : null
      if (!form || bypassFormsRef.current.delete(form) || form.dataset.skipSubmitConfirmation === 'true') return

      nativeEvent.preventDefault()
      nativeEvent.stopPropagation()

      const submitEvent = nativeEvent as SubmitEvent
      const submitter = submitEvent.submitter instanceof HTMLElement ? submitEvent.submitter : null
      const actionLabel = formActionLabel(form, submitter)
      setPending({
        form,
        submitter,
        title: `Confirm ${actionLabel}?`,
        description: `Review the information before you ${actionLabel.toLowerCase()}. This action will continue only after you confirm.`,
      })
    }

    document.addEventListener('submit', handleDocumentSubmit, true)
    return () => document.removeEventListener('submit', handleDocumentSubmit, true)
  }, [])

  function handleCancel() {
    setPending(null)
  }

  function handleConfirm() {
    const submission = pending
    if (!submission || confirmingRef.current) return

    confirmingRef.current = true
    setPending(null)
    window.setTimeout(() => {
      if (!submission.form.isConnected) {
        confirmingRef.current = false
        return
      }

      bypassFormsRef.current.add(submission.form)
      try {
        const submitter = submission.submitter instanceof HTMLButtonElement || submission.submitter instanceof HTMLInputElement
          ? submission.submitter
          : undefined
        submission.form.requestSubmit(submitter)
      } finally {
        bypassFormsRef.current.delete(submission.form)
        confirmingRef.current = false
      }
    }, 250)
  }

  return (
    <div className="contents">
      {children}
      <AlertDialog open={pending !== null} onOpenChange={(open) => !open && handleCancel()}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{pending?.title || 'Confirm form submission?'}</AlertDialogTitle>
            <AlertDialogDescription>{pending?.description || 'Review the information before submitting this form.'}</AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={handleCancel}>Cancel</AlertDialogCancel>
            <AlertDialogAction type="button" onClick={handleConfirm} disabled={confirmingRef.current}>Confirm</AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function noteAttachmentUrl(attachment: Record<string, any>): string {
  const explicitUrl = phaseField(attachment, 'view_url')
  if (explicitUrl !== '') return explicitUrl

  const attachmentKey = phaseField(attachment, 'attachment_key', phaseField(attachment, 'attachmentKey'))
  return attachmentKey !== '' ? `./?action=view_note_attachment&attachment_key=${encodeURIComponent(attachmentKey)}` : ''
}

function UiUxFlowChatAttachmentPicker({
  files,
  onChange,
}: {
  files: Array<File>
  onChange: (files: Array<File>) => void
}) {
  const [viewerImage, setViewerImage] = React.useState<Record<string, string> | null>(null)
  const [statusText, setStatusText] = React.useState('')
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const pasteRef = React.useRef<HTMLDivElement | null>(null)
  const previews = React.useMemo(
    () => files.map((file) => ({ file, url: URL.createObjectURL(file) })),
    [files],
  )

  React.useEffect(() => () => previews.forEach((preview) => URL.revokeObjectURL(preview.url)), [previews])

  function addFiles(nextFiles: Iterable<File>) {
    const images = Array.from(nextFiles).filter((file) => file.type.startsWith('image/'))
    if (images.length === 0) {
      setStatusText('No image file was found. Supported images: JPG, PNG, WEBP.')
      return
    }
    onChange([...files, ...images])
    setStatusText(`${images.length} image${images.length === 1 ? '' : 's'} ready for chat.`)
  }

  async function pasteFromClipboard() {
    if (navigator.clipboard && 'read' in navigator.clipboard) {
      try {
        const items = await navigator.clipboard.read()
        const pastedFiles: File[] = []
        for (const item of items) {
          for (const type of item.types) {
            if (!type.startsWith('image/')) continue
            const blob = await item.getType(type)
            const extension = type.split('/')[1] || 'png'
            pastedFiles.push(new File([blob], `chat-clipboard-${Date.now()}.${extension}`, { type }))
          }
        }
        addFiles(pastedFiles)
        return
      } catch {
        setStatusText('Clipboard access was blocked. Click the paste box, then press Ctrl+V.')
      }
    } else {
      setStatusText('Click the paste box, then press Ctrl+V to paste an image.')
    }
    pasteRef.current?.focus()
  }

  function handlePaste(event: React.ClipboardEvent<HTMLDivElement>) {
    const pastedFiles = Array.from(event.clipboardData.files || [])
    if (pastedFiles.length > 0) {
      event.preventDefault()
      addFiles(pastedFiles)
    }
  }

  return (
    <div className="grid gap-1.5 rounded-md border bg-background p-2">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <Label className="text-xs">Attachments</Label>
        <div className="flex items-center gap-1">
          {files.length > 0 ? <Badge variant="outline" className="h-6 px-1.5 text-[10px]">{files.length}</Badge> : null}
          <Tooltip>
            <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" className="rounded-full" title="Add screenshot" aria-label="Add screenshot" onClick={() => inputRef.current?.click()} />}>
              <ImagePlus />
            </TooltipTrigger>
            <TooltipContent>Add screenshot</TooltipContent>
          </Tooltip>
          <Tooltip>
            <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" className="rounded-full" title="Paste screenshot from clipboard" aria-label="Paste screenshot from clipboard" onClick={pasteFromClipboard} />}>
              <ClipboardList />
            </TooltipTrigger>
            <TooltipContent>Paste from clipboard</TooltipContent>
          </Tooltip>
        </div>
      </div>
      <input
        ref={inputRef}
        type="file"
        accept="image/png,image/jpeg,image/webp"
        multiple
        className="hidden"
        onChange={(event) => addFiles(event.currentTarget.files || [])}
      />
      <div
        ref={pasteRef}
        role="button"
        tabIndex={0}
        onPaste={handlePaste}
        className="flex min-h-8 items-center rounded-md border border-dashed bg-muted/10 px-2 py-1.5 text-[10px] text-muted-foreground outline-none focus:border-ring focus:ring-2 focus:ring-ring/20"
      >
        Focus here and press Ctrl+V to paste an image.
      </div>
      {statusText !== '' ? <p className="text-[10px] text-muted-foreground">{statusText}</p> : null}
      {previews.length > 0 ? (
        <div className="grid gap-1.5">
          {previews.map((preview, index) => (
            <div key={`${preview.file.name}-${preview.file.lastModified}-${index}`} className="flex items-center gap-2 rounded-md border border-blue-500/30 bg-blue-500/10 p-1.5">
              <button
                type="button"
                className="shrink-0 rounded outline-none focus:ring-2 focus:ring-ring/30"
                onClick={() => setViewerImage({ url: preview.url, title: preview.file.name, meta: 'Pending chat upload' })}
              >
                <img src={preview.url} alt={preview.file.name} className="h-10 w-14 rounded border object-cover" />
              </button>
              <div className="min-w-0 flex-1">
                <p className="truncate text-[11px] font-medium">{preview.file.name}</p>
                <p className="text-[10px] text-muted-foreground">Pending chat upload</p>
              </div>
              <Tooltip>
                <TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" className="shrink-0 rounded-full" title={`Remove ${preview.file.name}`} aria-label={`Remove ${preview.file.name}`} onClick={() => onChange(files.filter((_, fileIndex) => fileIndex !== index))} />}>
                  <Trash2 />
                </TooltipTrigger>
                <TooltipContent>Remove attachment</TooltipContent>
              </Tooltip>
            </div>
          ))}
        </div>
      ) : null}
      <Dialog open={!!viewerImage} onOpenChange={(open) => !open && setViewerImage(null)}>
        <DialogContent className="max-h-[94vh] overflow-y-auto sm:max-w-5xl">
          <DialogHeader>
            <DialogTitle>{phaseField(viewerImage, 'title', 'Chat Screenshot')}</DialogTitle>
            <DialogDescription>{phaseField(viewerImage, 'meta', 'Pending chat image')}</DialogDescription>
          </DialogHeader>
          {viewerImage ? (
            <div className="rounded-md border bg-background p-2">
              <img src={phaseField(viewerImage, 'url')} alt={phaseField(viewerImage, 'title', 'Chat Screenshot')} className="mx-auto max-h-[72vh] w-auto max-w-full rounded object-contain" />
            </div>
          ) : null}
        </DialogContent>
      </Dialog>
    </div>
  )
}

function NoteAttachmentPicker({
  csrf,
  noteKey = '',
  existing = [],
}: {
  csrf: string
  noteKey?: string
  existing?: Array<Record<string, any>>
}) {
  const [attachments, setAttachments] = React.useState<Array<Record<string, any>>>(existing)
  const [pendingFiles, setPendingFiles] = React.useState<Array<File>>([])
  const [deleteConfirmAttachment, setDeleteConfirmAttachment] = React.useState<Record<string, any> | null>(null)
  const [viewerImage, setViewerImage] = React.useState<Record<string, string> | null>(null)
  const [statusText, setStatusText] = React.useState('')
  const inputRef = React.useRef<HTMLInputElement | null>(null)
  const pasteRef = React.useRef<HTMLDivElement | null>(null)
  const existingSignature = React.useMemo(
    () => existing.map((attachment) => phaseField(attachment, 'attachment_key', phaseField(attachment, 'attachmentKey'))).join('|'),
    [existing],
  )

  React.useEffect(() => {
    setAttachments(existing)
    setPendingFiles([])
    setDeleteConfirmAttachment(null)
    setViewerImage(null)
    setStatusText('')
  }, [noteKey, existingSignature, existing])

  React.useEffect(() => {
    const input = inputRef.current
    if (!input) return

    if (pendingFiles.length === 0) {
      input.value = ''
      return
    }

    const transfer = new DataTransfer()
    pendingFiles.forEach((file) => transfer.items.add(file))
    input.files = transfer.files
  }, [pendingFiles])

  const previews = React.useMemo(
    () => pendingFiles.map((file) => ({ file, url: URL.createObjectURL(file) })),
    [pendingFiles],
  )

  React.useEffect(() => () => previews.forEach((preview) => URL.revokeObjectURL(preview.url)), [previews])

  function addFiles(files: Iterable<File>) {
    const images = Array.from(files).filter((file) => file.type.startsWith('image/'))
    if (images.length === 0) {
      setStatusText('No image file was found. Supported images: JPG, PNG, WEBP.')
      return
    }
    setPendingFiles((current) => [...current, ...images])
    setStatusText(`${images.length} image${images.length === 1 ? '' : 's'} ready to save.`)
  }

  async function pasteFromClipboard() {
    if (navigator.clipboard && 'read' in navigator.clipboard) {
      try {
        const items = await navigator.clipboard.read()
        const files: File[] = []
        for (const item of items) {
          for (const type of item.types) {
            if (!type.startsWith('image/')) continue
            const blob = await item.getType(type)
            const extension = type.split('/')[1] || 'png'
            files.push(new File([blob], `clipboard-image-${Date.now()}.${extension}`, { type }))
          }
        }
        addFiles(files)
        return
      } catch {
        setStatusText('Clipboard access was blocked. Click the paste box, then press Ctrl+V.')
      }
    } else {
      setStatusText('Click the paste box, then press Ctrl+V to paste an image.')
    }
    pasteRef.current?.focus()
  }

  function handlePaste(event: React.ClipboardEvent<HTMLDivElement>) {
    const files = Array.from(event.clipboardData.files || [])
    if (files.length > 0) {
      event.preventDefault()
      addFiles(files)
    }
  }

  async function deleteExistingAttachment(attachment: Record<string, any>) {
    const attachmentKey = phaseField(attachment, 'attachment_key', phaseField(attachment, 'attachmentKey'))
    if (attachmentKey === '') return

    const formData = new FormData()
    formData.set('csrf', csrf)
    formData.set('action', 'delete_note_attachment')
    formData.set('attachment_key', attachmentKey)

    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Image remove failed.')
        return
      }
      setAttachments((current) => current.filter((item) => phaseField(item, 'attachment_key', phaseField(item, 'attachmentKey')) !== attachmentKey))
      setStatusText('Image removed.')
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Image remove failed.')
    }
  }

  return (
    <div className="grid gap-3 rounded-md border bg-muted/10 p-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <Label className="text-sm">Screenshots / Images</Label>
          <p className="mt-1 text-xs text-muted-foreground">Add screenshots, upload images, or paste from clipboard. These images are included when AI reads the note.</p>
        </div>
        <Badge variant="outline">{attachments.length + pendingFiles.length} Items</Badge>
      </div>
      <input
        ref={inputRef}
        type="file"
        name="images[]"
        accept="image/png,image/jpeg,image/webp"
        multiple
        className="hidden"
        onChange={(event) => addFiles(event.currentTarget.files || [])}
      />
      <div className="flex flex-wrap gap-2">
        <Button type="button" variant="outline" size="sm" onClick={() => inputRef.current?.click()}>
          <ImagePlus />Add Screenshot / Upload Image
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={pasteFromClipboard}>
          <ClipboardList />Upload From Clipboard
        </Button>
      </div>
      <div
        ref={pasteRef}
        role="button"
        tabIndex={0}
        onPaste={handlePaste}
        className="rounded-md border border-dashed bg-background p-3 text-xs text-muted-foreground outline-none focus:border-ring focus:ring-2 focus:ring-ring/20"
      >
        Click here and press Ctrl+V to paste a screenshot from the clipboard.
      </div>
      {statusText !== '' ? <p className="text-xs text-muted-foreground">{statusText}</p> : null}
      {attachments.length > 0 || previews.length > 0 ? (
        <div className="grid gap-2 sm:grid-cols-2">
          {attachments.map((attachment) => {
            const attachmentKey = phaseField(attachment, 'attachment_key', phaseField(attachment, 'attachmentKey'))
            const imageUrl = noteAttachmentUrl(attachment)
            return (
              <div key={attachmentKey} className="flex gap-2 rounded-md border bg-background p-2">
                <button
                  type="button"
                  className="shrink-0 rounded outline-none focus:ring-2 focus:ring-ring/30"
                  onClick={() => setViewerImage({
                    url: imageUrl,
                    title: phaseField(attachment, 'original_name', 'Image attachment'),
                    meta: phaseField(attachment, 'mime_type', 'image'),
                  })}
                >
                  <img src={imageUrl} alt={phaseField(attachment, 'original_name', 'Note attachment')} className="h-16 w-20 rounded border object-cover" />
                </button>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-xs font-medium">{phaseField(attachment, 'original_name', 'Image attachment')}</p>
                  <p className="text-[10px] text-muted-foreground">{phaseField(attachment, 'mime_type', 'image')}</p>
                  <Button type="button" variant="outline" size="sm" className="mt-2 h-7 text-xs" onClick={() => setDeleteConfirmAttachment(attachment)}>
                    <Trash2 />Delete
                  </Button>
                </div>
              </div>
            )
          })}
          {previews.map((preview, index) => (
            <div key={`${preview.file.name}-${preview.file.lastModified}-${index}`} className="flex gap-2 rounded-md border border-blue-500/30 bg-blue-500/10 p-2">
              <button
                type="button"
                className="shrink-0 rounded outline-none focus:ring-2 focus:ring-ring/30"
                onClick={() => setViewerImage({
                  url: preview.url,
                  title: preview.file.name,
                  meta: 'Pending upload',
                })}
              >
                <img src={preview.url} alt={preview.file.name} className="h-16 w-20 rounded border object-cover" />
              </button>
              <div className="min-w-0 flex-1">
                <p className="truncate text-xs font-medium">{preview.file.name}</p>
                <p className="text-[10px] text-muted-foreground">Pending upload</p>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  className="mt-2 h-7 text-xs"
                  onClick={() => setPendingFiles((current) => current.filter((_, fileIndex) => fileIndex !== index))}
                >
                  <Trash2 />Delete
                </Button>
              </div>
            </div>
          ))}
        </div>
      ) : null}
      <Dialog open={!!viewerImage} onOpenChange={(open) => !open && setViewerImage(null)}>
        <DialogContent className="max-h-[94vh] overflow-y-auto sm:max-w-5xl">
          <DialogHeader>
            <DialogTitle>{phaseField(viewerImage, 'title', 'Image Attachment')}</DialogTitle>
            <DialogDescription>{phaseField(viewerImage, 'meta', 'Review note image')}</DialogDescription>
          </DialogHeader>
          {viewerImage ? (
            <div className="rounded-md border bg-background p-2">
              <img src={phaseField(viewerImage, 'url')} alt={phaseField(viewerImage, 'title', 'Image Attachment')} className="mx-auto max-h-[72vh] w-auto max-w-full rounded object-contain" />
            </div>
          ) : null}
        </DialogContent>
      </Dialog>
      <AlertDialog open={!!deleteConfirmAttachment} onOpenChange={(open) => !open && setDeleteConfirmAttachment(null)}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete Image Attachment?</AlertDialogTitle>
            <AlertDialogDescription>
              This removes the selected image from this review note and future AI note reading.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              type="button"
              onClick={() => {
                const attachment = deleteConfirmAttachment
                setDeleteConfirmAttachment(null)
                if (attachment) {
                  void deleteExistingAttachment(attachment)
                }
              }}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  )
}

function useAiJobMonitor() {
  const [job, setJob] = React.useState<AiJobPayload | null>(null)
  const [dialogOpen, setDialogOpen] = React.useState(false)

  React.useEffect(() => {
    function handleJobUpdate(event: Event) {
      const nextJob = (event as CustomEvent<AiJobPayload>).detail
      if (!nextJob?.id) return
      setJob(nextJob)
    }

    window.addEventListener(aiJobUpdatedEvent, handleJobUpdate)
    return () => window.removeEventListener(aiJobUpdatedEvent, handleJobUpdate)
  }, [])

  React.useEffect(() => {
    if (!job?.id || !['queued', 'running'].includes(job.status)) return undefined

    let cancelled = false
    const poll = async () => {
      try {
        const response = await fetch(`./?action=ai_job_status&job_id=${encodeURIComponent(job.id)}`, {
          headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
        })
        const result = await response.json()
        const nextJob = aiJobFromResult(result)
        if (!cancelled && nextJob) {
          setJob(nextJob)
          emitAiJobUpdate(nextJob)
        }
      } catch {
        if (!cancelled) {
          setJob((current) => current && current.id === job.id ? { ...current, status: 'unknown', message: 'AI status is temporarily unavailable.' } : current)
        }
      }
    }

    const timer = window.setInterval(poll, 2000)
    void poll()
    return () => {
      cancelled = true
      window.clearInterval(timer)
    }
  }, [job?.id, job?.status])

  React.useEffect(() => {
    if (!job?.id || ['queued', 'running'].includes(job.status) || dialogOpen) return undefined

    const timer = window.setTimeout(() => {
      setJob((current) => current && current.id === job.id ? null : current)
    }, 12000)

    return () => window.clearTimeout(timer)
  }, [dialogOpen, job?.id, job?.status])

  const activeJob = job?.id ? job : null

  return { job, activeJob, dialogOpen, setDialogOpen }
}

function AiJobDetailsDialog({
  job,
  open,
  onOpenChange,
}: {
  job: AiJobPayload | null
  open: boolean
  onOpenChange: (open: boolean) => void
}) {
  const [actionBusy, setActionBusy] = React.useState(false)
  if (!job) return null

  const resultText = job.result ? JSON.stringify(job.result, null, 2) : ''
  const contextText = job.context && Object.keys(job.context).length > 0 ? JSON.stringify(job.context, null, 2) : ''
  const memoryFiles = Array.isArray(job.memory?.included_files) ? job.memory.included_files : []
  const tokenUsage = job.token_usage || {}
  const checkpoints = Array.isArray(job.checkpoints) ? job.checkpoints : []
  const isProcessing = ['queued', 'running'].includes(job.status)

  async function submitJobAction(action: 'retry_ai_job' | 'cancel_ai_job' | 'rollback_ai_job') {
    setActionBusy(true)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', action)
    formData.set('job_id', job?.id || '')
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      const nextJob = aiJobFromResult(result)
      if (nextJob) emitAiJobUpdate(nextJob)
      if (!(result.ok || result.success)) window.alert(result.message || 'AI job action failed.')
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'AI job action failed.')
    } finally {
      setActionBusy(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Sparkles className="text-primary" />
            {job.label || 'AI Processing'}
          </DialogTitle>
          <DialogDescription>{job.message || 'AI is currently processing.'}</DialogDescription>
        </DialogHeader>
        <div className="grid gap-3">
          <div className="flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
            <Badge variant="outline">{job.status}</Badge>
            {job.segment_total ? <Badge variant="secondary">Segment {job.segment_index || 1}/{job.segment_total}{job.segment_label ? `: ${job.segment_label}` : ''}</Badge> : null}
            {job.memory_scope_id ? <Badge variant="secondary">{job.memory_scope_id}</Badge> : null}
            {job.updated_at ? <span>Updated {job.updated_at}</span> : null}
          </div>
          <div className="grid gap-2 rounded-md border bg-muted/20 p-3 sm:grid-cols-3 lg:grid-cols-6">
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Prompt</span><strong className="text-sm">{tokenUsage.prompt_tokens_estimated || 0}</strong></div>
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Memory</span><strong className="text-sm">{tokenUsage.context_tokens_estimated || 0}</strong></div>
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Response</span><strong className="text-sm">{tokenUsage.completion_tokens_estimated || 0}</strong></div>
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Estimated Total</span><strong className="text-sm">{tokenUsage.total_tokens_estimated || 0}</strong></div>
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Full Context</span><strong className="text-sm">{tokenUsage.full_context_tokens_estimated || 0}</strong></div>
            <div><span className="block text-[10px] uppercase tracking-wide text-muted-foreground">Saved</span><strong className="text-sm">{tokenUsage.tokens_saved_estimated || 0}</strong></div>
          </div>
          {memoryFiles.length > 0 ? (
            <div className="grid gap-2 rounded-md border bg-muted/10 p-3">
              <Label>Scoped Memory Read</Label>
              <div className="flex flex-wrap gap-1.5">
                {memoryFiles.map((file: string) => <Badge key={file} variant="outline" className="font-mono text-[10px]">{file}</Badge>)}
              </div>
            </div>
          ) : null}
          {job.prompt ? (
            <div className="grid gap-2">
              <Label>Current Prompt / Request</Label>
              <pre className="max-h-72 overflow-auto rounded-md border bg-muted/40 p-3 text-xs leading-5 whitespace-pre-wrap">{job.prompt}</pre>
            </div>
          ) : null}
          {contextText ? (
            <div className="grid gap-2">
              <Label>Context</Label>
              <pre className="max-h-48 overflow-auto rounded-md border bg-muted/40 p-3 text-xs leading-5 whitespace-pre-wrap">{contextText}</pre>
            </div>
          ) : null}
          {job.error ? (
            <div className="grid gap-2">
              <Label>Error</Label>
              <pre className="max-h-40 overflow-auto rounded-md border border-red-200 bg-red-50 p-3 text-xs leading-5 whitespace-pre-wrap text-red-700 dark:border-red-900/60 dark:bg-red-950 dark:text-red-300">{job.error}</pre>
            </div>
          ) : null}
          {resultText ? (
            <div className="grid gap-2">
              <Label>Latest Result</Label>
              <pre className="max-h-72 overflow-auto rounded-md border bg-muted/40 p-3 text-xs leading-5 whitespace-pre-wrap">{resultText}</pre>
            </div>
          ) : null}
          {checkpoints.length > 0 ? (
            <div className="grid gap-2">
              <Label>Processing Checkpoints</Label>
              <div className="grid gap-1.5">
                {checkpoints.map((checkpoint, index) => (
                  <div key={`${checkpoint.name || 'checkpoint'}-${index}`} className="flex items-center justify-between gap-3 rounded-md border px-3 py-2 text-xs">
                    <span className="font-medium">{checkpoint.name || 'Checkpoint'}</span>
                    <Badge variant="outline">{checkpoint.status || 'recorded'}</Badge>
                  </div>
                ))}
              </div>
            </div>
          ) : null}
        </div>
        <div className="flex flex-wrap items-center justify-end gap-2 border-t pt-4">
          <span className="text-xs text-muted-foreground">{isProcessing ? 'Background worker is active.' : 'This AI job can be inspected or retried.'}</span>
          <div className="flex gap-2">
            {isProcessing ? <Button type="button" variant="outline" size="sm" onClick={() => void submitJobAction('cancel_ai_job')} disabled={actionBusy}><RotateCcw />Cancel</Button> : null}
            {!isProcessing && job.status !== 'cancelled' && job.status !== 'rolled_back' ? <Button type="button" size="sm" onClick={() => void submitJobAction('retry_ai_job')} disabled={actionBusy}><RotateCcw />Retry</Button> : null}
            {!isProcessing && job.rollback?.eligible && job.status !== 'rolled_back' ? <Button type="button" variant="outline" size="sm" onClick={() => void submitJobAction('rollback_ai_job')} disabled={actionBusy}><RotateCcw />Rollback</Button> : null}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

function AiJobStatusIndicator({ job, onClick }: { job: AiJobPayload; onClick: () => void }) {
  const isProcessing = ['queued', 'running'].includes(job.status)

  return (
    <button
      type="button"
      className="inline-flex min-w-0 max-w-[min(22rem,35vw)] items-center gap-2 rounded-md border px-2 py-1 text-left text-xs font-medium text-foreground hover:bg-muted"
      onClick={onClick}
    >
      {isProcessing ? (
        <LoaderCircle className="size-4 shrink-0 animate-spin text-primary" aria-hidden="true" />
      ) : (
        <Sparkles className="size-4 shrink-0 text-primary" aria-hidden="true" />
      )}
      <span className="truncate">{job.message || 'AI is currently processing.'}</span>
      <span className="hidden text-muted-foreground sm:inline">Open AI Ops</span>
    </button>
  )
}

function PhaseDiagnosticsDialog() {
  const diagnostics = phaseData?.diagnostics || {}
  const items = Array.isArray(diagnostics.items) ? diagnostics.items : []
  const summary = diagnostics.summary || {}
  const issueCount = Number(summary.error || 0) + Number(summary.warning || 0)
  const [busy, setBusy] = React.useState(false)

  const registryIssue = items.some((item: Record<string, any>) => item.action === 'repair_database_registry' && item.repairable)

  async function runRepair(action: 'repair_codex_setup' | 'repair_database_registry') {
    setBusy(true)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', action)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Repair failed.')
        return
      }
      reloadPagePreservingScroll()
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Repair failed.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <Dialog>
      <DialogTrigger
        render={
          <Button type="button" variant={issueCount > 0 ? 'destructive' : 'outline'} size="icon-sm" aria-label="Open Phase Manager diagnostics" />
        }
      >
        {issueCount > 0 ? <Bell /> : <CheckCircle2 />}
        <span className="sr-only">{issueCount > 0 ? `${issueCount} Phase Manager notifications` : 'Phase Manager healthy'}</span>
      </DialogTrigger>
      <DialogContent className="max-h-[90vh] overflow-y-auto sm:max-w-3xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2"><Bell className="text-primary" />Phase Manager Notifications</DialogTitle>
          <DialogDescription>Database, memory, frontend, and Codex Chat discrepancies detected by the current project runtime.</DialogDescription>
        </DialogHeader>
        <div className="grid gap-3">
          <div className="grid grid-cols-3 gap-2 rounded-md border bg-muted/20 p-3 text-center text-xs">
            <div><span className="block text-muted-foreground">Healthy</span><strong className="text-green-600">{Number(summary.ok || 0)}</strong></div>
            <div><span className="block text-muted-foreground">Warnings</span><strong className="text-amber-600">{Number(summary.warning || 0)}</strong></div>
            <div><span className="block text-muted-foreground">Errors</span><strong className="text-red-600">{Number(summary.error || 0)}</strong></div>
          </div>
          <div className="grid gap-2">
            {items.map((item: Record<string, any>) => {
              const status = String(item.status || 'warning')
              const Icon = status === 'ok' ? CheckCircle2 : status === 'error' ? AlertTriangle : Bell
              return (
                <div key={String(item.key)} className="flex items-start gap-3 border-b py-4 first:pt-1 last:border-b-0 last:pb-1">
                  <Icon className={cn('mt-0.5 size-4 shrink-0', status === 'ok' ? 'text-green-600' : status === 'error' ? 'text-red-600' : 'text-amber-600')} />
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-start justify-between gap-2">
                      <p className="text-sm font-medium">{String(item.label || item.key || 'Diagnostic')}</p>
                      {item.repairable ? <Badge variant="outline">Repairable</Badge> : null}
                    </div>
                    <p className="mt-1 text-xs leading-5 text-muted-foreground">{String(item.details || '')}</p>
                    <div className="mt-3 border-t pt-3">
                      <p className="text-xs font-semibold">How to clear</p>
                      <ol className="mt-1 grid list-decimal gap-1 pl-4 text-xs leading-5 text-muted-foreground">
                        {(Array.isArray(item.instructions) ? item.instructions : ['Review the diagnostic details and recheck Notifications.']).map((instruction: unknown, instructionIndex: number) => (
                          <li key={`${String(item.key)}-instruction-${instructionIndex}`}>{String(instruction)}</li>
                        ))}
                      </ol>
                      <p className="mt-2 text-[11px] text-muted-foreground">Checked {String(item.checked_at || diagnostics.checked_at || '')}</p>
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
          <div className="flex flex-wrap items-center justify-end gap-2 border-t pt-4">
            <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href={phaseLocalHref({ view: 'settings' })}><Settings data-icon="inline-start" />AI Settings</a>
            <div className="flex flex-wrap gap-2">
              <Button type="button" variant="outline" size="sm" onClick={reloadPagePreservingScroll}><RotateCcw />Recheck</Button>
              {registryIssue ? <Button type="button" variant="outline" size="sm" onClick={() => void runRepair('repair_database_registry')} disabled={busy}><Wrench />Repair DB Registry</Button> : null}
              <Button type="button" size="sm" onClick={() => void runRepair('repair_codex_setup')} disabled={busy}><Wrench />{busy ? 'Repairing' : 'Repair AI Runtime'}</Button>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

function PhaseToolsDebugDialog() {
  const [open, setOpen] = React.useState(false)
  const [snapshot, setSnapshot] = React.useState<Record<string, any> | null>(null)
  const [memoryPreview, setMemoryPreview] = React.useState<Record<string, any> | null>(null)
  const [loading, setLoading] = React.useState(false)
  const [compactBusy, setCompactBusy] = React.useState(false)
  const [testBusy, setTestBusy] = React.useState(false)
  const [testResult, setTestResult] = React.useState<Record<string, any> | null>(null)
  const [copiedKey, setCopiedKey] = React.useState('')

  async function loadSnapshot() {
    setLoading(true)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'phase_tools_debug_snapshot')
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Phase Tools debug snapshot failed.')
        return
      }
      setSnapshot(result.data?.debug || null)
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Phase Tools debug snapshot failed.')
    } finally {
      setLoading(false)
    }
  }

  async function viewMemory(path: string) {
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'phase_tools_debug_view_memory')
    formData.set('memory_path', path)
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Memory file could not be opened.')
        return
      }
      setMemoryPreview(result.data?.memory || null)
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Memory file could not be opened.')
    }
  }

  async function runAiSmokeTest() {
    setTestBusy(true)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'run_ai_operation_codex_test')
    formData.set('operation_prompt', 'Return exactly this marker and nothing else: BUILDERX_PHASE_TOOLS_OK')
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const result = await response.json()
      setTestResult(result)
    } catch (error) {
      setTestResult({ ok: false, message: error instanceof Error ? error.message : 'AI smoke test failed.' })
    } finally {
      setTestBusy(false)
    }
  }

  async function compactMemory() {
    setCompactBusy(true)
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'phase_tools_compact_memory')
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const result = await response.json()
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Memory compaction failed.')
        return
      }
      setSnapshot(result.data?.debug || null)
      window.alert(`Removed ${Number(result.data?.compaction?.removed_files || 0)} old job memory file(s).`)
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Memory compaction failed.')
    } finally {
      setCompactBusy(false)
    }
  }

  async function copyDebugText(key: string, text: string) {
    try {
      await navigator.clipboard.writeText(text)
      setCopiedKey(key)
      window.setTimeout(() => setCopiedKey((current) => current === key ? '' : current), 1600)
    } catch {
      window.alert('Clipboard access is unavailable in this browser.')
    }
  }

  React.useEffect(() => {
    if (open) void loadSnapshot()
  }, [open])

  const directories = Array.isArray(snapshot?.directories) ? snapshot.directories : []
  const allFiles = directories.flatMap((directory: Record<string, any>) => (Array.isArray(directory.files) ? directory.files.map((file: Record<string, any>) => ({ ...file, directory: directory.label })) : []))
  const codexOnline = Boolean(snapshot?.codex_chat?.online)

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Open Phase Tools debug tools" />}>
        <Wrench />
      </DialogTrigger>
      <DialogContent className="h-[92vh] max-h-[92vh] grid-rows-[0_auto_minmax(0,1fr)] overflow-hidden sm:max-w-7xl">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2"><Wrench className="text-primary" />Phase Tools Debug</DialogTitle>
          <DialogDescription>Read-only memory inventory, retrieval status, AI runtime checks, and explicit test controls.</DialogDescription>
        </DialogHeader>
        <div className="grid min-h-0 grid-rows-[auto_auto_minmax(0,1fr)] gap-4 overflow-hidden">
          <div className="grid gap-2 sm:grid-cols-4">
            <div className="rounded-md border bg-muted/10 p-3 text-sm"><span className="block text-muted-foreground">Codex Chat</span><strong className={codexOnline ? 'text-emerald-600' : 'text-amber-600'}>{codexOnline ? 'Online' : 'Offline'}</strong></div>
            <div className="rounded-md border bg-muted/10 p-3 text-sm"><span className="block text-muted-foreground">Memory files</span><strong>{allFiles.length}</strong></div>
            <div className="rounded-md border bg-muted/10 p-3 text-sm"><span className="block text-muted-foreground">RAG documents</span><strong>{Number(snapshot?.retrieval_index?.document_count || 0)}</strong></div>
          </div>
          <div className="flex flex-wrap items-center justify-between gap-2 border-b pb-3">
            <div className="text-sm text-muted-foreground">Snapshot: {snapshot?.generated_at || 'Not loaded'}</div>
            <div className="flex flex-wrap gap-2">
              <Button type="button" variant="outline" size="sm" onClick={() => void loadSnapshot()} disabled={loading}><RotateCcw />{loading ? 'Refreshing' : 'Refresh Snapshot'}</Button>
              <Button type="button" variant="outline" size="sm" onClick={() => void compactMemory()} disabled={compactBusy}><Archive />{compactBusy ? 'Compacting' : 'Compact Job Memory'}</Button>
            </div>
          </div>
          <div className="grid min-h-0 gap-3 overflow-hidden lg:grid-cols-[minmax(0,1.1fr)_minmax(0,0.9fr)]">
            <div className="min-h-0 overflow-y-auto pr-1">
              <div>
                <h4 className="text-base font-semibold">Memory Paths and File Sizes</h4>
                <p className="mt-1 text-xs text-muted-foreground">Files are listed with bounded metadata. Select View to inspect a text file.</p>
              </div>
              {directories.map((directory: Record<string, any>) => (
                <div key={String(directory.label)} className="grid gap-2 rounded-md border p-3">
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <div><strong className="text-sm">{String(directory.label)}</strong><p className="mt-1 break-all font-mono text-xs text-muted-foreground">{String(directory.path || '')}</p></div>
                    <Badge variant={directory.exists ? 'outline' : 'secondary'}>{directory.exists ? `${Number(directory.file_count || 0)} files` : 'Missing'}</Badge>
                  </div>
                  <div className="flex flex-wrap gap-2 text-xs text-muted-foreground"><span>{formatBytes(Number(directory.bytes || 0))}</span><span>{directory.readable ? 'Readable' : 'Not readable'}</span><span>{directory.writable ? 'Writable' : 'Read-only'}</span></div>
                  {Array.isArray(directory.files) && directory.files.length > 0 ? <div className="grid max-h-44 gap-1 overflow-y-auto border-t pt-2">{directory.files.map((file: Record<string, any>) => <div key={String(file.path)} className="flex items-center gap-2 text-xs"><span className="min-w-0 flex-1 truncate font-mono" title={String(file.path)}>{String(file.path)}</span><span className="shrink-0 text-muted-foreground">{formatBytes(Number(file.bytes || 0))}</span>{file.readable ? <Button type="button" variant="ghost" size="icon-sm" title="View memory file" aria-label={`View ${String(file.name || file.path)}`} onClick={() => void viewMemory(String(file.path))}><Eye /></Button> : null}</div>)}</div> : null}
                </div>
              ))}
            </div>
            <div className="min-h-0 space-y-3 overflow-y-auto pr-1">
              <div className="grid gap-2 rounded-md border p-3">
                <h4 className="text-base font-semibold">Retrieval Index</h4>
                <p className="break-all font-mono text-xs text-muted-foreground">{String(snapshot?.retrieval_index?.path || 'Not loaded')}</p>
                <div className="grid gap-1 text-sm"><span>{Number(snapshot?.retrieval_index?.document_count || 0)} documents</span><span>{formatBytes(Number(snapshot?.retrieval_index?.bytes || 0))}</span><span>{String(snapshot?.retrieval_index?.strategy || 'Unavailable')}</span></div>
              </div>
              <div className="grid gap-2 rounded-md border p-3">
                <div className="flex items-center justify-between gap-2"><h4 className="text-base font-semibold">AI Test</h4><Badge variant="outline">Manual</Badge></div>
                <p className="text-xs text-muted-foreground">Runs one fresh marker test with BuilderX memory disabled. It may consume tokens.</p>
                <Button type="button" size="sm" onClick={() => void runAiSmokeTest()} disabled={testBusy}><TerminalSquare />{testBusy ? 'Testing AI' : 'Run AI Smoke Test'}</Button>
                {testResult ? <div className="grid gap-2 border-t pt-2"><div className="flex items-center justify-between gap-2"><div className="flex items-center gap-2"><Badge variant={testResult.ok ? 'secondary' : 'destructive'}>{testResult.ok ? 'Passed' : 'Failed'}</Badge>{testResult.data?.memory_mode === 'disabled' ? <Badge variant="outline">Memory disabled</Badge> : null}</div><Button type="button" variant="outline" size="sm" onClick={() => void copyDebugText('ai-test', JSON.stringify(testResult, null, 2))}><Copy />{copiedKey === 'ai-test' ? 'Copied' : 'Copy Result'}</Button></div><p className="text-sm text-muted-foreground">{String(testResult.message || '')}</p><pre className="max-h-64 overflow-auto whitespace-pre-wrap rounded-md bg-muted/20 p-2 text-xs">{JSON.stringify(testResult.data || {}, null, 2)}</pre></div> : null}
              </div>
              {memoryPreview ? <div className="grid gap-2 rounded-md border p-3"><div className="flex items-center justify-between gap-2"><h4 className="text-base font-semibold">Memory Preview</h4><div className="flex gap-1"><Button type="button" variant="outline" size="sm" onClick={() => void copyDebugText('memory-preview', String(memoryPreview.content || ''))}><Copy />{copiedKey === 'memory-preview' ? 'Copied' : 'Copy'}</Button><Button type="button" variant="ghost" size="icon-sm" aria-label="Close memory preview" onClick={() => setMemoryPreview(null)}><X /></Button></div></div><p className="break-all font-mono text-xs text-muted-foreground">{String(memoryPreview.path || '')} · {formatBytes(Number(memoryPreview.bytes || 0))}</p><pre className="max-h-[32rem] overflow-auto whitespace-pre-wrap rounded-md border bg-muted/10 p-3 text-xs leading-5">{String(memoryPreview.content || '')}</pre></div> : null}
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}

function PhaseSystemResetDialog() {
  const [open, setOpen] = React.useState(false)
  const [confirmation, setConfirmation] = React.useState('')
  const [busy, setBusy] = React.useState(false)
  const [error, setError] = React.useState('')

  function handleOpenChange(nextOpen: boolean) {
    if (busy) return
    setOpen(nextOpen)
    if (!nextOpen) {
      setConfirmation('')
      setError('')
    }
  }

  async function resetSystem() {
    if (confirmation !== 'RESET' || busy) return

    setBusy(true)
    setError('')
    const body = new FormData()
    body.set('action', 'reset_system_to_fresh_install')
    body.set('csrf', phaseData?.csrf || '')
    body.set('reset_confirmation', confirmation)

    try {
      const response = await fetch('./', {
        method: 'POST',
        body,
        headers: {
          'X-Requested-With': 'XMLHttpRequest',
          Accept: 'application/json',
        },
      })
      const result = await response.json()
      if (!response.ok || !result?.success) {
        throw new Error(String(result?.message || 'The system reset could not be completed.'))
      }
      setOpen(false)
      setConfirmation('')
      window.location.reload()
    } catch (resetError) {
      setError(resetError instanceof Error ? resetError.message : 'The system reset could not be completed.')
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <AlertDialog open={open} onOpenChange={handleOpenChange}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Reset system to fresh installed state?</AlertDialogTitle>
            <AlertDialogDescription>
              This permanently clears BuilderX database records, generated form records, phases, settings, and audit history. The current administrator account is recreated so you can sign in again. This cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="grid gap-2 py-2">
            <Label htmlFor="system-reset-confirmation">Type RESET to continue</Label>
            <Input
              id="system-reset-confirmation"
              value={confirmation}
              onChange={(event) => setConfirmation(event.target.value)}
              placeholder="RESET"
              autoComplete="off"
              spellCheck={false}
              disabled={busy}
            />
          </div>
          {error ? <p className="text-sm font-medium text-destructive" role="alert">{error}</p> : null}
          <AlertDialogFooter>
            <AlertDialogCancel disabled={busy}>Cancel</AlertDialogCancel>
            <AlertDialogAction
              type="button"
              disabled={busy || confirmation !== 'RESET'}
              onClick={(event) => {
                event.preventDefault()
                void resetSystem()
              }}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {busy ? <LoaderCircle className="animate-spin" /> : <RotateCcw />}
              {busy ? 'Resetting…' : 'Reset System'}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={() => setOpen(true)}
        className="border-destructive/50 text-destructive hover:bg-destructive/10 hover:text-destructive"
      >
        <RotateCcw data-icon="inline-start" />
        Reset System
      </Button>
    </>
  )
}

function PhaseShell({
  children,
  activeView,
  title,
  buildTarget,
  breadcrumbItems,
  footerLabel,
  theme,
  onThemeToggle,
}: {
  children: React.ReactNode
  activeView: PhasePayload['activeView']
  title: string
  buildTarget: string
  breadcrumbItems: string[]
  footerLabel: string
  theme: AdminThemeMode
  onThemeToggle: () => void
}) {
  const nextThemeLabel = theme === 'dark' ? 'Switch to light mode' : 'Switch to dark mode'
  const { loading: phaseNetworkLoading } = useShellNetworkLoading()
  const [messengerOpen, setMessengerOpen] = usePersistentMessengerOpen()
  const { unreadCount, clearUnread } = useMessengerNotifications(messengerOpen)
  const aiMonitor = useAiJobMonitor()
  const defaultSidebarOpen = React.useMemo(
    () => readBooleanCookie(sidebarCookieName) ?? true,
    [],
  )
  const openMessenger = React.useCallback(() => {
    clearUnread()
    setMessengerOpen(true)
  }, [clearUnread, setMessengerOpen])

  function openActiveAiJob() {
    const job = aiMonitor.activeJob
    if (!job) return
    window.dispatchEvent(new CustomEvent(phaseAiOperationOpenEvent, { detail: job }))
  }
  const displayTitle = messengerOpen ? 'Messenger' : title
  const displayBreadcrumbItems = messengerOpen ? [...breadcrumbItems.slice(0, 1), 'Messenger'] : breadcrumbItems

  return (
    <TooltipProvider>
      <SidebarProvider
        defaultOpen={defaultSidebarOpen}
        style={{
          '--sidebar-width': '256px',
        } as React.CSSProperties}
      >
        <AdminSidebarMobilePersistence defaultOpen={defaultSidebarOpen} />
        <PhaseSidebar activeView={activeView} onNavigate={() => setMessengerOpen(false)} />
        <SidebarInset className="h-svh max-h-svh min-h-0 overflow-hidden">
          <header className="sticky top-0 z-30 flex min-h-14 shrink-0 flex-wrap items-center justify-between gap-3 border-b bg-background/95 px-4 py-2 shadow-[0_1px_0_rgba(15,23,42,0.04)] backdrop-blur transition-[width,height] ease-linear group-has-data-[collapsible=icon]/sidebar-wrapper:min-h-12">
            <div className="flex min-w-0 flex-1 items-center gap-2">
              <SidebarTrigger className="-ml-1" />
              <Separator orientation="vertical" className="mr-2 data-vertical:h-4 data-vertical:self-auto" />
              <div className="hidden size-7 shrink-0 items-center justify-center rounded-md bg-primary text-primary-foreground sm:flex">
                <Activity className="size-4" />
              </div>
              <div className="min-w-0">
                <div className="flex min-w-0 items-center gap-2">
                  <h1 className="truncate text-sm font-semibold tracking-normal">{displayTitle}</h1>
                  <Badge variant="outline" className="hidden shrink-0 text-[10px] font-normal sm:inline-flex">Workspace</Badge>
                </div>
                <ShadcnBreadcrumb>
                  <BreadcrumbList>
                    {displayBreadcrumbItems.map((item, index) => (
                      <React.Fragment key={`${item}-${index}`}>
                        {index > 0 && <BreadcrumbSeparator />}
                        <BreadcrumbItem>
                          <BreadcrumbPage>{item}</BreadcrumbPage>
                        </BreadcrumbItem>
                      </React.Fragment>
                    ))}
                  </BreadcrumbList>
                </ShadcnBreadcrumb>
              </div>
            </div>
            <Separator orientation="vertical" className="hidden data-vertical:h-6 data-vertical:self-auto lg:block" />
            <nav aria-label="Workspace links" className="hidden flex-wrap items-center justify-end gap-1.5 xl:flex">
              <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href="https://ui.shadcn.com/" target="_blank" rel="noreferrer">
                <ExternalLink data-icon="inline-start" />
                shadcn/ui
              </a>
              <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href={phaseHref()}><Users data-icon="inline-start" />User Portal</a>
              <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href={phaseHref('administrator/')}><ShieldCheck data-icon="inline-start" />Administrator</a>
              <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href={phaseHref('phases/?phase=')}><FolderKanban data-icon="inline-start" />Phase Manager</a>
            </nav>
            <Separator orientation="vertical" className="hidden data-vertical:h-6 data-vertical:self-auto lg:block" />
            <div aria-label="Header buttons" className="flex flex-wrap items-center justify-end gap-2">
              {aiMonitor.activeJob ? <AiJobStatusIndicator job={aiMonitor.activeJob} onClick={openActiveAiJob} /> : null}
              <PhaseDiagnosticsDialog />
              <PhaseToolsDebugDialog />
              <PhaseSystemResetDialog />
              <a className={buttonClassName({ variant: 'outline', size: 'sm' })} href="./installation.php">
                <Download data-icon="inline-start" />
                Installer
              </a>
              <MessengerHeaderButton onOpen={openMessenger} unreadCount={unreadCount} />
              <HeaderControlSeparator />
              <Tooltip>
                <TooltipTrigger
                  render={
                    <Button type="button" variant="outline" size="icon-sm" aria-label={nextThemeLabel} onClick={onThemeToggle} />
                  }
                >
                  {theme === 'dark' ? <Sun /> : <Moon />}
                </TooltipTrigger>
                <TooltipContent>{nextThemeLabel}</TooltipContent>
              </Tooltip>
              <form method="post" className="contents">
                <input type="hidden" name="csrf" value={phaseData?.csrf || ''} />
                <input type="hidden" name="action" value="phase_logout" />
                <input type="hidden" name="target" value="builder" />
                <Button type="submit" variant="outline" size="sm"><LogIn data-icon="inline-start" />Sign Out</Button>
              </form>
            </div>
          </header>
          <SampleShellProgressBar active={phaseNetworkLoading} />

          <main className={cn('min-h-0 flex-1 bg-muted/20', messengerOpen ? 'flex flex-col overflow-hidden p-4' : activeView === 'data-structure-v2' || activeView === 'ai-flow' || activeView === 'ai-operation' ? 'flex flex-col gap-3 overflow-y-auto p-3' : activeView === 'phases' ? 'flex flex-col gap-4 overflow-y-auto p-4 [&>*]:shrink-0' : 'flex flex-col gap-4 overflow-y-auto p-4')}>
            {messengerOpen ? <MessengerWorkspace onClose={() => setMessengerOpen(false)} /> : <><PhaseFlashMessage flash={phaseData?.flash ?? null} />{children}</>}
          </main>

          <footer className="sticky bottom-0 z-20 mt-auto grid min-h-11 shrink-0 grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-3 border-t bg-background/95 px-4 text-xs text-muted-foreground backdrop-blur">
            <span className="inline-flex min-w-0 items-center gap-2">
              <span className="size-1.5 shrink-0 rounded-full bg-emerald-500" aria-hidden="true" />
              <span className="truncate">{footerLabel}</span>
            </span>
            <SampleFooterLoadingIndicator active={phaseNetworkLoading} />
            <span className="min-w-0 justify-self-end truncate text-right font-mono text-[10px] uppercase tracking-[0.08em]">Mode: Preview · {buildTarget}</span>
          </footer>
          {activeView !== 'flow' ? <UiUxFlowView operationOnly /> : null}
        </SidebarInset>
      </SidebarProvider>
    </TooltipProvider>
  )
}

