function phasePercent(done: number, total: number): number {
  return total > 0 ? Math.round((done / total) * 100) : 0
}

function phaseStatusVariant(status: string): 'default' | 'secondary' | 'destructive' | 'outline' {
  if (status === 'Completed') return 'default'
  if (status === 'Blocked' || status === 'Failed') return 'destructive'
  if (status === 'For Review' || status === 'Running' || status === 'Rolled back') return 'outline'

  return 'secondary'
}

function ProjectPhaseMetricGrid({ phases, tasks }: { phases: Array<Record<string, any>>; tasks: Array<Record<string, any>> }) {
  const totalTasks = phases.reduce((total, phase) => total + phaseNumber(phase, 'task_count'), 0)
  const completedTasks = phases.reduce((total, phase) => total + phaseNumber(phase, 'completed_count'), 0)
  const totalChecklist = phases.reduce((total, phase) => total + phaseNumber(phase, 'checklist_count'), 0)
  const completedChecklist = phases.reduce((total, phase) => total + phaseNumber(phase, 'checklist_done_count'), 0)
  const selectedNotes = tasks.reduce((total, task) => total + phaseNumber(task, 'note_count'), 0)
  const selectedPendingNotes = tasks.reduce((total, task) => total + phaseNumber(task, 'pending_note_count'), 0)
  const metrics = [
    { label: 'Phases', value: phases.length, detail: `${phases.filter((phase) => phaseField(phase, 'phase_status') === 'Completed').length} completed`, icon: FolderKanban },
    { label: 'Task Progress', value: `${phasePercent(completedTasks, totalTasks)}%`, detail: `${completedTasks} of ${totalTasks} tasks`, icon: ClipboardList },
    { label: 'Checklist Progress', value: `${phasePercent(completedChecklist, totalChecklist)}%`, detail: `${completedChecklist} of ${totalChecklist} checks`, icon: BookOpen },
    { label: 'Selected Notes', value: selectedNotes, detail: `${selectedPendingNotes} pending review`, icon: Activity },
  ]

  return (
    <section className="grid overflow-hidden rounded-lg border bg-card sm:grid-cols-2 lg:grid-cols-4">
      {metrics.map((metric) => {
        const Icon = metric.icon
        return (
          <div key={metric.label} className="min-w-0 border-b border-r p-4 last:border-r-0 lg:border-b-0">
            <div className="mb-4 flex items-center justify-between gap-3">
              <Icon className="text-muted-foreground" aria-hidden="true" />
              <span className="truncate text-xs font-medium text-muted-foreground">{metric.label}</span>
            </div>
            <div className="text-3xl font-bold leading-none tracking-normal">{metric.value}</div>
            <p className="mt-2 truncate text-xs text-muted-foreground">{metric.detail}</p>
          </div>
        )
      })}
    </section>
  )
}

