type DisplayRoadmapTask = {
  taskId: string
  taskTitle: string
  taskDescription: string
  taskType: string
  track: 'web' | 'android' | 'shared'
  route: string
  apiEndpoint: string
  tableName: string
  resourceRefs: string[]
  indicators: string[]
  suggestions: Record<string, any>
  subTasks: Array<{ subtaskId: string; subtaskTitle: string; subtaskDescription: string; acceptanceCriteria: string[]; dependsOn: string[]; todos: Array<{ todoId: string; todoTitle: string; todoDescription: string; todoType: string; status: string }> }>
  legacyTrack?: 'web' | 'android'
  legacyIndex?: number
}

function displayRoadmapTasks(phase: Record<string, any>, phaseId: string): DisplayRoadmapTask[] {
  if (Array.isArray(phase.tasks)) {
    return phase.tasks.map((task: Record<string, any>, index: number) => ({
      taskId: String(task.taskId || `${phaseId}-TASK-${String(index + 1).padStart(2, '0')}`),
      taskTitle: String(task.taskTitle || `Task ${index + 1}`),
      taskDescription: String(task.taskDescription || ''),
      taskType: String(task.taskType || 'vertical_slice'),
      track: ['web', 'android', 'shared'].includes(task.track) ? task.track : 'shared',
      route: String(task.route || ''),
      apiEndpoint: String(task.apiEndpoint || ''),
      tableName: String(task.tableName || task.suggestions?.tableName || ''),
      resourceRefs: Array.isArray(task.resourceRefs) ? task.resourceRefs.map((ref: unknown) => String(ref)) : [],
      indicators: Array.isArray(task.indicators) ? task.indicators.map((indicator: unknown) => String(indicator)) : [],
      suggestions: task.suggestions && typeof task.suggestions === 'object' ? task.suggestions : { tableName: '', tableFields: [], relatedFiles: [], forms: [] },
      subTasks: Array.isArray(task.subTasks) ? task.subTasks.map((subtask: Record<string, any>, subtaskIndex: number) => ({ subtaskId: String(subtask.subtaskId || `${phaseId}-TASK-${index + 1}-SUB-${subtaskIndex + 1}`), subtaskTitle: String(subtask.subtaskTitle || `Sub-task ${subtaskIndex + 1}`), subtaskDescription: String(subtask.subtaskDescription || ''), acceptanceCriteria: Array.isArray(subtask.acceptanceCriteria) ? subtask.acceptanceCriteria.map((criterion: unknown) => String(criterion)) : [], dependsOn: Array.isArray(subtask.dependsOn) ? subtask.dependsOn.map((dependency: unknown) => String(dependency)) : [], todos: Array.isArray(subtask.todos) ? subtask.todos.map((todo: Record<string, any>, todoIndex: number) => ({ todoId: String(todo.todoId || `${phaseId}-TASK-${index + 1}-SUB-${subtaskIndex + 1}-TODO-${todoIndex + 1}`), todoTitle: String(todo.todoTitle || `Todo ${todoIndex + 1}`), todoDescription: String(todo.todoDescription || ''), todoType: String(todo.todoType || 'implementation'), status: String(todo.status || 'Pending') })) : [] })) : [],
    }))
  }
  return (['web', 'android'] as const).flatMap((track) => {
    const field = track === 'web' ? 'webTrackTasks' : 'androidTrackTasks'
    return (Array.isArray(phase[field]) ? phase[field] : []).map((task: unknown, index: number) => ({
      taskId: `${phaseId}-${track.toUpperCase()}-TASK-${String(index + 1).padStart(2, '0')}`,
      taskTitle: `${track === 'web' ? 'Web' : 'Android'} task ${index + 1}`,
      taskDescription: String(task),
      taskType: 'vertical_slice',
      track,
      route: '',
      apiEndpoint: '',
      tableName: '',
      resourceRefs: [],
      indicators: [],
      suggestions: { tableName: '', tableFields: [], relatedFiles: [], forms: [] },
      subTasks: [],
      legacyTrack: track,
      legacyIndex: index,
    }))
  })
}

function roadmapTaskInvolvement(task: DisplayRoadmapTask) {
  const indicatorSet = new Set(task.indicators)
  const taskType = task.taskType.trim().toLowerCase()
  const suggestedForms = Array.isArray(task.suggestions?.forms) ? task.suggestions.forms : []
  const suggestedFields = Array.isArray(task.suggestions?.tableFields) ? task.suggestions.tableFields : []
  const hasForm = indicatorSet.has('forms') || taskType === 'form' || suggestedForms.length > 0
  const hasDatabase = indicatorSet.has('database') || indicatorSet.has('crud') || taskType === 'database' || Boolean(task.tableName.trim()) || Boolean(String(task.suggestions?.tableName || '').trim()) || suggestedFields.length > 0
  const indicators = [...new Set([
    ...task.indicators,
    ...(hasForm ? ['forms'] : []),
    ...(hasDatabase ? ['database'] : []),
  ])]
  const summary = [hasForm ? 'Form involved' : '', hasDatabase ? 'Database involved' : ''].filter(Boolean).join(' · ')
  return { hasForm, hasDatabase, indicators, summary }
}

const roadmapTodoInvolvementIcons: Record<string, React.ElementType> = {
  view: Eye,
  insert: Plus,
  edit: Pencil,
  delete: Trash2,
  database: Database,
  api: Workflow,
  forms: PenLine,
  authentication: KeyRound,
  authorization: ShieldCheck,
  validation: CheckCircle2,
  testing: TestTube2,
  files: FileText,
  implementation: Wrench,
  analysis: FileBarChart,
  verification: CheckCircle2,
}

const roadmapTodoInvolvementLabels: Record<string, string> = {
  view: 'View or screen involved',
  insert: 'Insert or create involved',
  edit: 'Edit or update involved',
  delete: 'Delete involved',
  database: 'Database involved',
  api: 'API involved',
  forms: 'Form involved',
  authentication: 'Authentication involved',
  authorization: 'Authorization involved',
  validation: 'Validation involved',
  testing: 'Testing involved',
  files: 'Files involved',
  implementation: 'Implementation todo',
  analysis: 'Analysis todo',
  verification: 'Verification todo',
}

function roadmapTodoInvolvement(todo: DisplayRoadmapTask['subTasks'][number]['todos'][number], task: DisplayRoadmapTask) {
  const source = `${todo.todoType} ${todo.todoTitle} ${todo.todoDescription}`.toLowerCase()
  const taskIndicators = new Set(task.indicators)
  const taskType = task.taskType.trim().toLowerCase()
  const involvement = new Set<string>()
  const has = (patterns: RegExp[]) => patterns.some((pattern) => pattern.test(source))
  const add = (key: string) => involvement.add(key)

  if (has([/\bview\b/, /\bscreen\b/, /\bpage\b/, /\bportal\b/, /\brender\b/, /\bdisplay\b/, /\blist\b/, /\bread-only\b/]) || taskType === 'page') add('view')
  if (has([/\binsert\b/, /\bcreate\b/, /\badd\b/, /\bsave\b/, /\bpersist\b/])) add('insert')
  if (has([/\bedit\b/, /\bupdate\b/, /\bmodify\b/, /\bchange\b/])) add('edit')
  if (has([/\bdelete\b/, /\bremove\b/, /\barchive\b/])) add('delete')
  if (taskIndicators.has('api') || taskType === 'api' || Boolean(task.apiEndpoint.trim()) || has([/\bapi\b/, /\bendpoint\b/, /\bservice\b/, /\brequest\b/])) add('api')
  if (roadmapTaskInvolvement(task).hasDatabase || has([/\bdatabase\b/, /\btable\b/, /\bsql\b/, /\bquery\b/, /\brecord\b/, /\bstorage\b/])) add('database')
  if (roadmapTaskInvolvement(task).hasForm || has([/\bform\b/, /\binput\b/, /\bfield\b/])) add('forms')
  if (taskIndicators.has('authentication') || has([/\bauthentication\b/, /\bsign-in\b/, /\bsession\b/, /\btoken\b/])) add('authentication')
  if (taskIndicators.has('authorization') || has([/\bauthorization\b/, /\bpermission\b/, /\brole\b/, /\baccess\b/])) add('authorization')
  if (taskIndicators.has('validation') || has([/\bvalidation\b/, /\binvariant\b/, /\binput rules?\b/])) add('validation')
  if (taskIndicators.has('testing') || has([/\btest\b/, /\bverify\b/, /\bverification\b/, /\bacceptance\b/])) add('testing')
  if (taskIndicators.has('files') || has([/\bfile\b/, /\bimage\b/, /\bscreenshot\b/, /\bupload\b/])) add('files')
  if (involvement.size === 0) add(['analysis', 'implementation', 'verification'].includes(todo.todoType.toLowerCase()) ? todo.todoType.toLowerCase() : 'implementation')

  return Array.from(involvement).map((key) => ({ key, label: roadmapTodoInvolvementLabels[key] || key, Icon: roadmapTodoInvolvementIcons[key] || Wrench }))
}

function ExecutionRoadmapTab({
  phaseKey,
  roadmap,
  progress,
  busyTaskKey,
  children,
  beforeQuickJump,
  moduleCatalog,
  onTaskChange,
}: {
  phaseKey: string
  roadmap: Record<string, any>
  progress: Record<string, boolean>
  busyTaskKey: string
  children?: React.ReactNode
  beforeQuickJump?: React.ReactNode
  moduleCatalog?: Array<Record<string, any>>
  onTaskChange: (phaseId: string, taskId: string, subtaskId: string, todoId: string, completed: boolean, legacyTrack?: 'web' | 'android', legacyIndex?: number) => void
}) {
  const overview = roadmap?.phaseExecutionOverview && typeof roadmap.phaseExecutionOverview === 'object' ? roadmap.phaseExecutionOverview : {}
  const phases = Array.isArray(roadmap?.phases) ? roadmap.phases : []
  const hasRoadmap = phases.length > 0
  const displayPhases = phases.map((phase: Record<string, any>, phaseIndex: number) => {
    const phaseId = String(phase.phaseId || `PHASE-${String(phaseIndex + 1).padStart(2, '0')}`)
    return { phase, phaseId, phaseIndex, tasks: displayRoadmapTasks(phase, phaseId) }
  })
  const progressItems = displayPhases.flatMap(({ phaseId, tasks }) => tasks.flatMap((task) => [
    { key: task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`, task },
    ...task.subTasks.flatMap((subtask) => [{ key: `${phaseId}:${task.taskId}:${subtask.subtaskId}`, task }, ...subtask.todos.map((todo) => ({ key: `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`, task }))]),
  ]))
  const completedItems = progressItems.filter(({ key }) => progress[key] === true).length
  const completionPercent = progressItems.length > 0 ? Math.round((completedItems / progressItems.length) * 100) : 0
  const taskCount = displayPhases.reduce((total, { tasks }) => total + tasks.length, 0)
  const subtaskCount = displayPhases.reduce((total, { tasks }) => total + tasks.reduce((taskTotal, task) => taskTotal + task.subTasks.length, 0), 0)
  const roadmapPhaseAnchor = (phaseId: string) => `execution-${phaseId.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
  const roadmapModuleAnchor = (moduleId: string, moduleIndex: number) => `execution-module-${(moduleId || `module-${moduleIndex + 1}`).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '')}`
  const moduleGroups = (() => {
    const catalog = Array.isArray(moduleCatalog) ? moduleCatalog : []
    const assignedPhaseIds = new Set<string>()
    const groups = catalog.map((module, moduleIndex) => {
      const moduleId = String(module.moduleId || `MODULE-${String(moduleIndex + 1).padStart(3, '0')}`)
      const modulePhases = displayPhases.filter(({ phase, phaseId }) => String(phase.moduleId || '') === moduleId && !assignedPhaseIds.has(phaseId))
      modulePhases.forEach(({ phaseId }) => assignedPhaseIds.add(phaseId))
      return { module, moduleId, modulePhases, moduleIndex }
    }).filter(({ modulePhases }) => modulePhases.length > 0)
    const unassignedPhases = displayPhases.filter(({ phaseId }) => !assignedPhaseIds.has(phaseId))
    if (unassignedPhases.length > 0) groups.push({ module: { moduleTitle: catalog.length > 0 ? 'Other roadmap phases' : 'Execution roadmap' }, moduleId: 'unassigned', modulePhases: unassignedPhases, moduleIndex: groups.length })
    return groups.length > 0 ? groups : [{ module: { moduleTitle: 'Execution roadmap' }, moduleId: 'roadmap', modulePhases: displayPhases, moduleIndex: 0 }]
  })()

  if (!hasRoadmap) {
    return (
      <div className="grid gap-4">
        {children}{beforeQuickJump}
        <div id="execution-roadmap-overview" className="scroll-mt-24 grid min-h-60 place-items-center rounded-md bg-muted/20 p-6 text-center">
          <div className="max-w-xl">
            <TerminalSquare className="mx-auto size-8 text-muted-foreground" />
            <h2 className="mt-3 text-base font-semibold">No execution roadmap yet</h2>
            <p className="mt-2 text-sm leading-6 text-muted-foreground">Complete System Architecture &amp; Build Manifest, then generate the Phase → Task → Sub-task roadmap. Suggestions are advisory and remain inside the Phase Builder artifact.</p>
          </div>
        </div>
      </div>
    )
  }

  return (
    <div className="grid gap-4">
      <section id="execution-roadmap-overview" className="scroll-mt-24 rounded-lg bg-gradient-to-br from-emerald-500/10 via-background to-sky-500/10 p-5">
        <div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-semibold uppercase tracking-wider text-emerald-700 dark:text-emerald-300">Implementation decomposition</p><h2 className="mt-1 text-xl font-semibold">{String(overview.projectTitle || 'Execution & UI/UX Roadmap · Saved phase analysis')}</h2><p className="mt-2 max-w-4xl text-sm leading-6 text-muted-foreground">{String(overview.strategy || 'Stage 1 phase analysis is saved below. Run Stage 2 to add implementation tasks.')}</p></div><div className="flex flex-wrap items-center gap-2">{['builderx.execution-roadmap.v1', 'builderx.execution-roadmap.v2', 'builderx.execution-roadmap.v3'].includes(String(roadmap.schemaVersion || '')) ? <ExecutionRoadmapPhaseManagerExport phaseKey={phaseKey} roadmap={roadmap} /> : null}<Badge variant="outline">{phases.length} Phases</Badge><Badge variant="outline">{taskCount} Tasks</Badge><Badge variant="outline">{subtaskCount} Sub-tasks</Badge><Badge>{completedItems} / {progressItems.length} Done</Badge><Tooltip><TooltipTrigger render={<Button type="button" variant="outline" size="icon-sm" aria-label="Refresh Execution Roadmap content" title="Refresh Execution Roadmap content" onClick={reloadPagePreservingScroll} />}><RotateCcw /></TooltipTrigger><TooltipContent>Refresh saved roadmap content</TooltipContent></Tooltip></div></div>
        <div className="mt-4"><div className="flex items-center justify-between gap-2 text-xs"><span className="text-muted-foreground">Overall implementation progress</span><strong>{completionPercent}%</strong></div><div className="mt-2 h-2 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-emerald-500 transition-all" style={{ width: `${completionPercent}%` }} /></div></div>
      </section>

      {children}{beforeQuickJump}
      <nav aria-label="Execution roadmap module quick jumps" className="sticky top-[6.6rem] z-20 flex self-start flex-wrap items-center gap-2 rounded-lg bg-background/95 p-3 shadow-[0_0_18px_rgba(16,185,129,0.14),0_8px_24px_rgba(0,0,0,0.24)] ring-1 ring-emerald-400/10 backdrop-blur supports-[backdrop-filter]:bg-background/85"><span className="mr-1 text-[11px] font-semibold uppercase tracking-wider text-muted-foreground">Module list</span><a href="#execution-roadmap-overview" className={buttonClassName({ variant: 'outline', size: 'sm' })}>Overview</a>{moduleGroups.map(({ module, moduleId, modulePhases, moduleIndex }) => <a key={`roadmap-module-jump-${moduleId}`} href={`#${roadmapModuleAnchor(moduleId, moduleIndex)}`} title={`${String(module.moduleTitle || module.moduleKey || moduleId)} · ${modulePhases.length} phases`} className={buttonClassName({ variant: 'outline', size: 'sm' })}>{String(module.moduleTitle || module.moduleKey || moduleId)}</a>)}</nav>

      <div className="grid gap-4">
        {moduleGroups.map(({ module, moduleId, modulePhases, moduleIndex }) => (
          <section id={roadmapModuleAnchor(moduleId, moduleIndex)} key={moduleId} className="scroll-mt-[12rem] grid gap-3 rounded-lg bg-muted/10 p-3">
            <div className="flex flex-wrap items-start justify-between gap-3 px-1"><div><p className="text-[11px] font-semibold uppercase tracking-wider text-emerald-700 dark:text-emerald-300">Module {moduleIndex + 1}</p><h3 className="mt-1 text-base font-semibold">{String(module.moduleTitle || module.moduleKey || moduleId)}</h3><p className="mt-1 text-xs text-muted-foreground">{modulePhases.length} phase{modulePhases.length === 1 ? '' : 's'} generated for this module.</p></div><Badge variant="outline">{moduleId}</Badge></div>
            <div className="grid gap-4">
        {modulePhases.map(({ phase, phaseId, tasks, phaseIndex }) => {
          const phaseProgressItems = tasks.flatMap((task) => [task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`, ...task.subTasks.flatMap((subtask) => [`${phaseId}:${task.taskId}:${subtask.subtaskId}`, ...subtask.todos.map((todo) => `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`)])])
          const phaseDone = phaseProgressItems.filter((taskKey) => progress[taskKey] === true).length
          const status = phaseDone === phaseProgressItems.length && phaseProgressItems.length > 0 ? 'Completed' : phaseDone > 0 ? 'In Progress' : String(phase.status || 'Pending')
          return (
            <section id={roadmapPhaseAnchor(phaseId)} key={phaseId} className="scroll-mt-24 overflow-hidden rounded-lg bg-muted/5">
              <div className="flex flex-wrap items-start justify-between gap-3 border-b bg-muted/20 p-4"><div className="flex min-w-0 gap-3"><span className="grid size-9 shrink-0 place-items-center rounded-full border font-mono text-xs">{phaseIndex + 1}</span><div className="min-w-0"><p className="font-mono text-[11px] text-sky-700 dark:text-sky-300">{phaseId}</p><h3 className="mt-1 font-semibold">{String(phase.phaseTitle || phase.phaseName || `Phase ${phaseIndex + 1}`)}</h3><p className="mt-1 text-sm leading-6 text-muted-foreground">{String(phase.phaseDescription || phase.description || '')}</p></div></div><div className="flex flex-wrap items-center justify-end gap-2"><Badge variant={status === 'Completed' ? 'default' : status === 'In Progress' ? 'secondary' : 'outline'}>{status} · {phaseDone}/{phaseProgressItems.length}</Badge><a href="#execution-roadmap-overview" className={buttonClassName({ variant: 'ghost', size: 'sm' })}>Back to top</a></div></div>
              {phase.phaseType || Array.isArray(phase.systemFlow) || phase.proposedResources ? <div className="grid gap-3 border-b bg-background/40 p-4"><div className="flex flex-wrap items-center gap-2"><Badge variant="secondary">{String(phase.phaseType || 'implementation')}</Badge>{phase.entryPoint ? <span className="text-xs text-muted-foreground">Entry: {String(phase.entryPoint)}</span> : null}{phase.exitPoint ? <span className="text-xs text-muted-foreground">Exit: {String(phase.exitPoint)}</span> : null}</div>{Array.isArray(phase.systemFlow) && phase.systemFlow.length > 0 ? <Collapsible><CollapsibleTrigger className="flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Workflow className="size-3.5" />System flow<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="mt-3 grid gap-2">{phase.systemFlow.map((step: Record<string, any>, flowIndex: number) => <div key={String(step.flowStepId || flowIndex)} className="grid gap-1 rounded-md bg-muted/30 p-3 text-xs"><div className="flex flex-wrap items-center gap-2"><span className="font-mono text-muted-foreground">{String(step.flowStepId || `FLOW-${flowIndex + 1}`)}</span><Badge variant="outline">{String(step.nodeType || 'step')}</Badge><span className="font-medium">{String(step.from || 'Start')} → {String(step.to || 'Next')}</span></div><p className="text-muted-foreground">{String(step.action || '')}</p>{step.route || step.apiRef ? <p className="font-mono text-muted-foreground">{[step.route, step.apiRef].filter(Boolean).join(' · ')}</p> : null}</div>)}</CollapsibleContent></Collapsible> : null}{phase.proposedResources ? <Collapsible><CollapsibleTrigger className="flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Database className="size-3.5" />Proposed implementation resources<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="mt-3 grid gap-2 text-xs sm:grid-cols-2">{(['forms', 'tables', 'apis', 'backgroundProcesses', 'reports', 'analytics'] as const).map((resourceType) => { const resources = Array.isArray(phase.proposedResources[resourceType]) ? phase.proposedResources[resourceType] : []; return <div key={resourceType} className="rounded-md bg-muted/30 p-3"><p className="font-medium">{resourceType}</p><p className="mt-1 text-muted-foreground">{resources.length > 0 ? resources.map((resource: Record<string, any>) => String(resource.formName || resource.tableName || resource.name || resource.operation || 'Proposed resource')).join(' · ') : 'None proposed'}</p></div>})}</CollapsibleContent></Collapsible> : null}</div> : null}
              <div className="grid gap-3 p-4">
                {tasks.map((task) => {
                  const taskKey = task.legacyTrack ? `${phaseId}:${task.legacyTrack}:${task.legacyIndex}` : `${phaseId}:${task.taskId}`
                  const taskCompleted = progress[taskKey] === true
                  const taskBusy = busyTaskKey === taskKey
                  const suggestions = task.suggestions
                  const hasSuggestions = Boolean(suggestions.tableName || suggestions.tableFields?.length || suggestions.relatedFiles?.length || suggestions.forms?.length)
                  const involvement = roadmapTaskInvolvement(task)
                  const indicatorTone = involvement.summary ? 'border-orange-500/60 bg-orange-500/15 text-orange-700 shadow-[0_0_9px_rgba(249,115,22,0.24)] dark:text-orange-300' : 'border-sky-500/30 bg-sky-500/10 text-sky-600 dark:text-sky-300'
                  return <article key={taskKey} className={cn('grid gap-3 rounded-md bg-background/70 p-4', taskCompleted && 'bg-emerald-500/5', taskBusy && 'opacity-60')}>
                    <div className="flex items-start gap-3"><input type="checkbox" className={cn('mt-1 size-4 shrink-0 accent-emerald-600', involvement.summary && 'accent-orange-500')} checked={taskCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, '', '', event.target.checked, task.legacyTrack, task.legacyIndex)} aria-label={`Complete ${task.taskTitle}`} /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><span className={cn('font-mono text-[10px] text-muted-foreground', involvement.summary && 'text-orange-700 dark:text-orange-300')} title={involvement.summary || undefined}>{task.taskId}</span><Badge variant="outline" className={involvement.summary ? 'border-orange-500/50 bg-orange-500/10 text-orange-700 dark:text-orange-300' : undefined}>{task.taskType}</Badge><Badge variant="outline">{task.track === 'android' ? 'Android' : task.track === 'web' ? 'Web' : 'Shared'}</Badge><div className="flex items-center gap-1" aria-label={involvement.summary ? `Task indicators · ${involvement.summary}` : 'Task indicators'}>{involvement.indicators.map((indicator) => { const IndicatorIcon = executionRoadmapIndicatorIcons[indicator] || Wrench; const indicatorLabel = executionRoadmapIndicatorLabels[indicator] || indicator; const inferred = !task.indicators.includes(indicator); const tooltipLabel = inferred ? `${indicatorLabel} involved (inferred from task resources)` : indicatorLabel; return <Tooltip key={indicator}><TooltipTrigger render={<span className={cn('grid size-6 place-items-center rounded-full border', indicatorTone)} aria-label={tooltipLabel} title={tooltipLabel}><IndicatorIcon className="size-3.5" /></span>} /><TooltipContent>{tooltipLabel}</TooltipContent></Tooltip> })}</div></div><h4 className={cn('mt-1 text-sm font-semibold', taskCompleted && 'text-muted-foreground line-through')}>{task.taskTitle}</h4><p className="mt-1 text-sm leading-5 text-muted-foreground">{task.taskDescription}</p>{task.route || task.apiEndpoint || task.tableName ? <p className="mt-2 text-xs text-muted-foreground">{[task.route, task.apiEndpoint, task.tableName ? `table: ${task.tableName}` : ''].filter(Boolean).join(' · ')}</p> : null}</div>{taskBusy ? <LoaderCircle className="size-4 shrink-0 animate-spin" /> : taskCompleted ? <CheckCircle2 className="size-4 shrink-0 text-emerald-600 dark:text-emerald-300" /> : null}</div>
                    {task.subTasks.length > 0 ? <ol className="ml-7 grid gap-3 border-l pl-4">{task.subTasks.map((subtask) => { const subtaskKey = `${phaseId}:${task.taskId}:${subtask.subtaskId}`; const subtaskCompleted = progress[subtaskKey] === true; const subtaskBusy = busyTaskKey === subtaskKey; return <li key={subtaskKey} className="grid gap-2"><label className={cn('flex cursor-pointer items-start gap-2 text-sm', subtaskBusy && 'opacity-60')}><input type="checkbox" className="mt-0.5 size-4 shrink-0 accent-sky-600" checked={subtaskCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, subtask.subtaskId, '', event.target.checked)} aria-label={`Complete ${subtask.subtaskTitle}`} /><span className={cn('min-w-0', subtaskCompleted && 'text-muted-foreground line-through')}><span className="mr-2 font-mono text-[10px] text-muted-foreground">{subtask.subtaskId}</span>{subtask.subtaskTitle}{subtask.subtaskDescription ? <span className="mt-1 block text-xs leading-5 text-muted-foreground">{subtask.subtaskDescription}</span> : null}</span></label>{subtask.acceptanceCriteria.length > 0 ? <div className="ml-6 text-xs text-muted-foreground"><span className="font-medium text-foreground">Acceptance:</span> {subtask.acceptanceCriteria.join(' · ')}</div> : null}{subtask.todos.length > 0 ? <ul className="ml-6 grid gap-1 border-l pl-3">{subtask.todos.map((todo) => { const todoKey = `${phaseId}:${task.taskId}:${subtask.subtaskId}:${todo.todoId}`; const todoCompleted = progress[todoKey] === true; return <li key={todoKey}><label className="flex cursor-pointer items-start gap-2 text-xs"><input type="checkbox" className="mt-0.5 size-3.5 shrink-0 accent-violet-600" checked={todoCompleted} disabled={busyTaskKey !== ''} onChange={(event) => onTaskChange(phaseId, task.taskId, subtask.subtaskId, todo.todoId, event.target.checked)} aria-label={`Complete ${todo.todoTitle}`} /><span className={cn(todoCompleted && 'text-muted-foreground line-through')}><span className="mr-1 font-medium">{todo.todoTitle}</span><span className="text-muted-foreground">· {todo.todoDescription}</span></span></label></li>})}</ul> : null}</li>})}</ol> : null}
                    {hasSuggestions ? <Collapsible><CollapsibleTrigger className="ml-7 flex items-center gap-2 text-xs font-medium text-muted-foreground hover:text-foreground"><Wrench className="size-3.5" />Implementation suggestions<ChevronDown className="size-3.5" /></CollapsibleTrigger><CollapsibleContent className="ml-7 mt-3 grid gap-3 border-l pl-4 text-xs"><div className="grid gap-1"><span className="font-medium">Suggested table</span><span className="font-mono text-muted-foreground">{String(suggestions.tableName || 'No table suggestion')}</span>{Array.isArray(suggestions.tableFields) && suggestions.tableFields.length > 0 ? <span className="font-mono text-muted-foreground">Fields: {suggestions.tableFields.map((field: Record<string, any>) => `${field.name} ${field.type}${field.nullable ? '' : ' NOT NULL'}`).join(' · ')}</span> : null}</div>{Array.isArray(suggestions.forms) && suggestions.forms.length > 0 ? <div className="grid gap-1"><span className="font-medium">Suggested forms</span><span className="text-muted-foreground">{suggestions.forms.map((form: Record<string, any>) => `${form.name} · ${form.action}`).join(' · ')}</span></div> : null}{Array.isArray(suggestions.relatedFiles) && suggestions.relatedFiles.length > 0 ? <div className="grid gap-1"><span className="font-medium">Related files</span><span className="font-mono text-muted-foreground">{suggestions.relatedFiles.join(' · ')}</span></div> : null}</CollapsibleContent></Collapsible> : null}
                  </article>
                })}
              </div>
            </section>
          )
        })}
            </div>
          </section>
        ))}
      </div>
    </div>
  )
}

