    if (key === 'database') return 'M -3 -3 H 3 M -3 0 H 3 M -3 3 H 3 M -4 -5 H 4 V 5 H -4 Z'
    if (key === 'form') return 'M -4 -5 H 4 V 5 H -4 Z M -2 -2 H 2 M -2 1 H 2'
    if (key === 'ui') return 'M -5 3 H 5 M -4 -4 H 4 V 1 H -4 Z M -1 1 V 3'
    if (key === 'security') return 'M 0 -5 L 4 -3 V 1 C 3 4, 1.5 5, 0 5 C -1.5 5, -3 4, -4 1 V -3 Z'
    return 'M -4 0 L -1.2 3.2 L 5 -4 M -5 -5 H 5 V 5 H -5 Z'
