  function operationTimeLabel(): string {
    return new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' })
  }

  function operationMetricNumber(value: unknown): number | null {
    const numeric = Number(value)
    return Number.isFinite(numeric) ? numeric : null
  }

  function appendOperationStreamEntry(entry: { time: string; worker: string; text: string }) {
    setOperationStream((current) => [...current, entry].slice(-24))
  }

  function updateOperationWorkerTask(worker: string, updates: Partial<AiOperationWorkerTask>) {
    setOperationWorkerTasks((current) => current.map((task) => (
      task.worker === worker
        ? {
            ...task,
            ...updates,
            done: Math.max(0, Math.min(updates.done ?? task.done, updates.total ?? task.total)),
            total: Math.max(0, updates.total ?? task.total),
          }
        : task
    )))
  }

  async function postAiOperationAction(action: string, payload: Record<string, string> = {}) {
    const formData = new FormData()
    formData.set('csrf', csrf)
    formData.set('action', action)
    Object.entries(payload).forEach(([key, value]) => formData.set(key, value))
    const response = await fetch(window.location.href, {
      method: 'POST',
      body: formData,
      headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
    })
    const contentType = response.headers.get('content-type') || ''
    const rawText = await response.text()
    if (!contentType.includes('application/json')) {
      throw new Error(`AI Operation returned HTML instead of JSON. HTTP ${response.status}.`)
    }
    return JSON.parse(rawText)
  }

