  function groupId(group: Record<string, any>, index: number): string {
    return phaseField(group, 'key', `${flowKey}-${sectionKey}-${phaseField(group, 'label', 'group')}-${index}`)
  }

  function groupPosition(group: Record<string, any>, index: number, defaultY: number): ProjectFlowNodePosition {
    const id = groupId(group, index)
    const saved = positions[id]

    return saved || { x: flowCanvasInsetX, y: Math.round(defaultY + flowCanvasInsetY) }
  }

  function subphaseId(group: Record<string, any>, groupIndex: number, subphase: Record<string, any>, subphaseIndex: number): string {
    return phaseField(subphase, 'key', `${groupId(group, groupIndex)}-subphase-${subphaseIndex}`)
  }

  function subphasePosition(group: Record<string, any>, groupIndex: number, subphase: Record<string, any>, subphaseIndex: number, defaultPosition: ProjectFlowNodePosition): ProjectFlowNodePosition {
    const id = subphaseId(group, groupIndex, subphase, subphaseIndex)
    const saved = positions[id]

    return saved || defaultPosition
  }

  function noteId(subphaseKey: string, note: Record<string, any>, noteIndex: number): string {
    return phaseField(note, 'key', `${subphaseKey}-note-${noteIndex}`)
  }

  function noteDatabaseId(noteKey: string): string {
    return `${noteKey}-database`
  }

  function noteFormId(noteKey: string, formId = ''): string {
    return formId === '' || formId === 'form-legacy' ? `${noteKey}-form` : `${noteKey}-form-${formId}`
  }

  function noteCrudTarget(note: Record<string, any>): string {
    const target = phaseField(note, 'crudTargetTable', 'NONE').trim()

    return target === '' ? 'NONE' : target
  }

  function noteHasDatabaseTarget(note: Record<string, any>): boolean {
    const target = noteCrudTarget(note).toUpperCase()

    return target !== 'NONE'
  }

  function noteDatabaseLabel(note: Record<string, any>): string {
    const target = noteCrudTarget(note)
    const newTableName = phaseField(note, 'crudNewTableName')

    return target.toUpperCase() === 'NEW' ? (newTableName || 'New Table') : target
  }

  function noteExistingDatabaseTable(note: Record<string, any>): string {
    const target = noteCrudTarget(note)
    const upper = target.toUpperCase()

    return upper !== 'NONE' && upper !== 'NEW' ? target : ''
  }

  function notePlannedDatabaseTable(note: Record<string, any> | null | undefined): string {
    if (!note || noteCrudTarget(note).toUpperCase() !== 'NEW') return ''

    const tableName = phaseField(note, 'crudNewTableName').trim()
    return tableName !== '' ? tableName : databaseAiSuggestedTableName(note)
  }

  function formDatabaseTableOptions(note: Record<string, any> | null | undefined): string[] {
    const options = Array.isArray(phaseData?.databaseTables) ? [...phaseData.databaseTables] : []
    const plannedTable = notePlannedDatabaseTable(note)
    if (plannedTable !== '' && !options.includes(plannedTable)) {
      options.unshift(plannedTable)
    }

    return options
  }

  function databaseStructureFields(tableName: string): Array<Record<string, any>> {
    const fields = phaseData?.databaseFieldDetails?.[tableName]
    if (Array.isArray(fields)) return fields

    return crudFieldOptionsFor(tableName).map((fieldName) => ({ fieldName, type: '', nullable: '', default: '', key: '', extra: '', comment: '' }))
  }

  function isInternalFormField(fieldName: string): boolean {
    return ['x_Id', 'zStatus', 'zCreated_At', 'zUpdated_At', 'zServerTimeStamp', 'x_id', 'zstatus', 'zcreated_at', 'zupdated_at', 'zservertimestamp', 'created_at', 'updated_at'].includes(fieldName)
  }

  function formControlForField(fieldName: string, type: string): string {
    const name = fieldName.toLowerCase()
    const dataType = type.toLowerCase()
    if (/(description|details|content|snippet|notes|message|address)/.test(name) || dataType.includes('text')) return 'textarea'
    if (/(url|link|website)/.test(name)) return 'url'
    if (name.includes('email')) return 'email'
    if (/(_at|date|time)/.test(name)) return 'datetime'
    if (/(rank|count|amount|total|number|qty|quantity|int|decimal|price)/.test(name) || /(int|decimal|float|double)/.test(dataType)) return 'number'
    if (/(status|type|category|role|group)/.test(name)) return 'select'

    return 'text'
  }

  function formLabelForField(fieldName: string): string {
    return fieldName
      .replace(/^.+?_/, '')
      .split('_')
      .filter(Boolean)
      .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
      .join(' ') || fieldName
  }

  function formSourceFieldSignature(field: Record<string, any>): string {
    return [
      phaseField(field, 'data_type', phaseField(field, 'type')).toUpperCase(),
      phaseField(field, 'source_nullable', phaseField(field, 'nullable')).toUpperCase(),
      phaseField(field, 'source_default', phaseField(field, 'default')),
      phaseField(field, 'source_extra', phaseField(field, 'extra')).toLowerCase(),
      phaseField(field, 'source_comment', phaseField(field, 'comment')),
    ].join('|')
  }

  function plannedDatabaseStructureFields(note: Record<string, any> | null, tableName: string): Array<Record<string, any>> {
    const suggestions = Array.isArray(note?.crudAiPayload?.table_suggestions) ? note?.crudAiPayload?.table_suggestions : []
    const suggestion = suggestions.find((item: Record<string, any>) => phaseField(item, 'table_name') === tableName)
    const fields = Array.isArray(suggestion?.fields) ? suggestion.fields : []

    return fields
      .filter((field: Record<string, any>) => !isInternalFormField(phaseField(field, 'field_name')))
      .map((field: Record<string, any>) => ({
        fieldName: phaseField(field, 'field_name'),
        type: phaseField(field, 'data_type', 'VARCHAR(255)'),
        nullable: field.required === true ? 'NO' : 'YES',
        default: 'NULL',
        key: '',
        extra: '',
        comment: phaseField(field, 'purpose', 'Planned database field.'),
      }))
      .filter((field: Record<string, any>) => field.fieldName !== '')
  }

  function databaseDevopsGuideSections(note: Record<string, any> | null): Array<{ key: string; label: string; items: string[] }> {
    const guide = note?.crudAiPayload?.devops_guide
    if (!guide || typeof guide !== 'object' || Array.isArray(guide)) return []

    const labels: Record<string, string> = {
      migration: 'Migration',
      validation: 'Validation',
      indexes: 'Indexes',
      security: 'Security',
      deployment: 'Deployment',
    }

    return Object.entries(labels)
      .map(([key, label]) => ({
        key,
        label,
        items: Array.isArray(guide[key]) ? guide[key].map((item: any) => String(item).trim()).filter(Boolean).slice(0, 3) : [],
      }))
      .filter((section) => section.items.length > 0)
  }

  function databaseStructureSettingsFor(note: Record<string, any> | null): Record<string, any> {
    const savedSettings = note?.crudAiPayload?.table_settings
    return {
      engine: phaseField(savedSettings, 'engine', 'InnoDB'),
      charset: phaseField(savedSettings, 'charset', 'utf8mb4'),
      collation: phaseField(savedSettings, 'collation', 'utf8mb4_unicode_ci'),
      timestamps: savedSettings?.timestamps !== false,
      soft_delete: savedSettings?.soft_delete === true,
      migration_required: savedSettings?.migration_required !== false,
    }
  }

  function databaseStructureEditableRows(note: Record<string, any> | null, tableName: string): Array<Record<string, any>> {
    const physicalRows = databaseStructureFields(tableName)
    const rows = physicalRows.length > 0 ? physicalRows : plannedDatabaseStructureFields(note, tableName)
    return rows.map((field) => ({
      fieldName: phaseField(field, 'fieldName', phaseField(field, 'field_name', '')),
      type: phaseField(field, 'type', phaseField(field, 'data_type', 'VARCHAR(255)')),
      nullable: phaseField(field, 'nullable', field.required === true ? 'NO' : 'YES').toUpperCase() === 'NO' ? 'NO' : 'YES',
      default: phaseField(field, 'default', 'NULL'),
      key: phaseField(field, 'key', ''),
      extra: phaseField(field, 'extra', ''),
      comment: phaseField(field, 'comment', phaseField(field, 'purpose', '')),
    }))
  }

  function closeDatabaseStructureEditor() {
    setDatabaseStructureTable('')
    setDatabaseStructureNote(null)
    setDatabaseStructureAiMessage('')
    setDatabaseStructureDraftTable('')
    setDatabaseStructureDraftFields([])
    setDatabaseStructureDraftSettings({})
    setDatabaseStructureDraftDirty(false)
    setDatabaseStructureSettingsOpen(false)
    setDatabaseStructureSaveMessage('')
  }

  function openDatabaseStructureEditor(note: Record<string, any>, tableName: string) {
    setDatabaseStructureTable(tableName)
    setDatabaseStructureNote(note)
    setDatabaseStructureDraftTable(tableName)
    setDatabaseStructureDraftFields(databaseStructureEditableRows(note, tableName))
    setDatabaseStructureDraftSettings(databaseStructureSettingsFor(note))
    setDatabaseStructureDraftDirty(false)
    setDatabaseStructureSettingsOpen(false)
    setDatabaseStructureSaveMessage('')
  }

  function updateDatabaseStructureDraftField(index: number, key: string, value: string) {
    setDatabaseStructureDraftFields((current) => current.map((field, fieldIndex) => fieldIndex === index ? { ...field, [key]: value } : field))
    setDatabaseStructureDraftDirty(true)
    setDatabaseStructureSaveMessage('')
  }

  function addDatabaseStructureDraftField() {
    setDatabaseStructureDraftFields((current) => [...current, {
      fieldName: `new_field_${current.length + 1}`,
      type: 'VARCHAR(255)',
      nullable: 'YES',
      default: 'NULL',
      key: '',
      extra: '',
      comment: '',
    }])
    setDatabaseStructureDraftDirty(true)
    setDatabaseStructureSaveMessage('')
  }

  function deleteDatabaseStructureDraftField(index: number) {
    setDatabaseStructureDraftFields((current) => current.filter((_, fieldIndex) => fieldIndex !== index))
    setDatabaseStructureDraftDirty(true)
    setDatabaseStructureSaveMessage('')
  }

  async function saveDatabaseStructureDraft() {
    const noteKey = phaseField(databaseStructureNote, 'noteKey')
    const tableName = databaseStructureDraftTable.trim()
    if (noteKey === '' || tableName === '' || databaseStructureSaveBusy || !databaseStructureIsPlanned) return

    const effectiveNote = effectiveDatabaseNote(databaseStructureNote)
    const existingPayload = effectiveNote.crudAiPayload && typeof effectiveNote.crudAiPayload === 'object' && !Array.isArray(effectiveNote.crudAiPayload)
      ? effectiveNote.crudAiPayload
      : {}
    const existingSuggestions = Array.isArray(existingPayload.table_suggestions) ? existingPayload.table_suggestions : []
    const existingSuggestion = existingSuggestions.find((suggestion: Record<string, any>) => phaseField(suggestion, 'table_name') === databaseStructureTable) || existingSuggestions[0] || {}
    const nextPayload = {
      ...existingPayload,
      generation_mode: 'database_fields_with_devops_guide',
      recommended_table: tableName,
      table_suggestions: [{
        ...existingSuggestion,
        table_name: tableName,
        mode: 'NEW',
        fields: databaseStructureDraftFields.map((field) => ({
          field_name: phaseField(field, 'fieldName').trim(),
          data_type: phaseField(field, 'type', 'VARCHAR(255)').trim(),
          purpose: phaseField(field, 'comment').trim(),
          required: phaseField(field, 'nullable', 'YES').toUpperCase() === 'NO',
          nullable: phaseField(field, 'nullable', 'YES').toUpperCase() === 'NO' ? 'NO' : 'YES',
          default: phaseField(field, 'default', 'NULL').trim(),
          key: phaseField(field, 'key').trim(),
          extra: phaseField(field, 'extra').trim(),
        })).filter((field) => field.field_name !== ''),
      }],
      table_settings: databaseStructureDraftSettings,
    }
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'save_note_database_structure')
    formData.set('note_key', noteKey)
    formData.set('crud_ai_payload', JSON.stringify(nextPayload))

    setDatabaseStructureSaveBusy(true)
    setDatabaseStructureSaveMessage('Saving database draft...')
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        setDatabaseStructureSaveMessage(`Action returned HTML instead of JSON. HTTP ${response.status}.`)
        return
      }
      const result = JSON.parse(rawText)
      if (!(result.ok || result.success)) {
        setDatabaseStructureSaveMessage(result.message || 'Database draft could not be saved.')
        return
      }
      const savedPayload = result.data?.crud_ai_payload && typeof result.data.crud_ai_payload === 'object' ? result.data.crud_ai_payload : nextPayload
      const nextOverride = { crudAiPayload: savedPayload, crudAiChat: effectiveNote.crudAiChat || [] }
      setDatabaseStructureOverrides((current) => ({ ...current, [noteKey]: nextOverride }))
      setDatabaseStructureNote((current) => current ? { ...current, ...nextOverride } : current)
      const savedTableName = phaseField(savedPayload.table_suggestions?.[0], 'table_name', tableName)
      setDatabaseStructureDraftTable(savedTableName)
      setDatabaseStructureDraftDirty(false)
      setDatabaseStructureSaveMessage('Database draft saved. No physical table was changed.')
    } catch (error) {
      setDatabaseStructureSaveMessage(error instanceof Error ? error.message : 'Database draft could not be saved.')
    } finally {
      setDatabaseStructureSaveBusy(false)
    }
  }

  function presetFormFields(note: Record<string, any> | null): Array<Record<string, any>> {
    const tableName = note ? noteExistingDatabaseTable(note) || phaseField(note?.formAiPayload, 'database_table') || notePlannedDatabaseTable(note) : ''
    if (tableName === '') return []

    const sourceFields = databaseStructureFields(tableName)
    const fields = sourceFields.length > 0 ? sourceFields : plannedDatabaseStructureFields(note, tableName)

    return fields
      .filter((field) => !isInternalFormField(phaseField(field, 'fieldName')))
      .map((field) => {
        const fieldName = phaseField(field, 'fieldName')
        const type = phaseField(field, 'type', 'VARCHAR(255)')
        const sourceField = {
          data_type: type,
          source_nullable: phaseField(field, 'nullable'),
          source_default: phaseField(field, 'default'),
          source_extra: phaseField(field, 'extra'),
          source_comment: phaseField(field, 'comment'),
        }

        return {
          field_name: fieldName,
          label: formLabelForField(fieldName),
          control: formControlForField(fieldName, type),
          required: phaseField(field, 'nullable', 'YES').toUpperCase() === 'NO' && phaseField(field, 'default') === 'NULL',
          placeholder: '',
          help_text: phaseField(field, 'comment', 'Preset database field.'),
          width: formControlForField(fieldName, type) === 'textarea' ? 'full' : 'half',
          data_type: type,
          source_nullable: phaseField(field, 'nullable'),
          source_default: phaseField(field, 'default'),
          source_extra: phaseField(field, 'extra'),
          source_comment: phaseField(field, 'comment'),
          source_signature: formSourceFieldSignature(sourceField),
          source: 'preset',
        }
      })
  }

  function effectiveFormNote(note: Record<string, any>): Record<string, any> {
    const noteKey = phaseField(note, 'noteKey')
    return noteKey !== '' && formBuilderOverrides[noteKey] ? { ...note, ...formBuilderOverrides[noteKey] } : note
  }

  function effectiveDataSymbolNote(note: Record<string, any>): Record<string, any> {
    const noteKey = phaseField(note, 'noteKey')
    return noteKey !== '' && dataSymbolOverrides[noteKey]
      ? { ...note, dataSymbols: { symbols: dataSymbolOverrides[noteKey] } }
      : note
  }

  function effectiveDatabaseNote(note: Record<string, any>): Record<string, any> {
    const noteKey = phaseField(note, 'noteKey')
    return noteKey !== '' && databaseStructureOverrides[noteKey]
      ? { ...note, ...databaseStructureOverrides[noteKey] }
      : note
  }

  async function stopDatabaseStructureAi() {
    if (!databaseStructureAiBusy) return

    const jobId = databaseStructureAiJobId
    setDatabaseStructureAiMessage('Stopping AI request...')
    if (jobId === '') {
      databaseStructureAiAbortRef.current?.abort()
      databaseStructureAiAbortRef.current = null
      setDatabaseStructureAiBusy(false)
      setDatabaseStructureAiMessage('AI request stopped before the background job was created.')
      return
    }

    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'cancel_ai_job')
    formData.set('job_id', jobId)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const result = await response.json()
      const nextJob = aiJobFromResult(result)
      if (nextJob) emitAiJobUpdate(nextJob)
      if (!(result.ok || result.success)) {
        setDatabaseStructureAiMessage(result.message || 'AI request could not be stopped.')
        return
      }
      setDatabaseStructureAiJobId('')
      setDatabaseStructureAiBusy(false)
      setDatabaseStructureAiMessage('AI request stopped. No new database draft was applied.')
    } catch (error) {
      setDatabaseStructureAiMessage(error instanceof Error ? error.message : 'AI request could not be stopped.')
    }
  }

  async function generateDatabaseStructureFields(note: Record<string, any> | null) {
    const noteKey = phaseField(note, 'noteKey')
    const isPlannedNote = note !== null && noteExistingDatabaseTable(note) === ''
    if (!note || noteKey === '' || !isPlannedNote || databaseStructureAiBusy) return

    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'suggest_note_database_codex')
    formData.set('note_key', noteKey)
    formData.set('user_message', 'Generate the basic fields for this planned table from the phase, task, and note description. Apply the saved database naming conventions, default fields, data-type rules, and existing schema constraints. Also return a compact DevOps guide in the same response covering migration, validation, indexes, security, and deployment or rollback. Return a concise draft field list with purpose and required status. Do not create or migrate the physical table.')

    setDatabaseStructureAiBusy(true)
    setDatabaseStructureAiMessage('AI is preparing a scoped database field draft...')
    const abortController = new AbortController()
    databaseStructureAiAbortRef.current = abortController
    let waitingForJob = false
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        signal: abortController.signal,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      const backgroundJob = aiJobFromResult(result)
      if (backgroundJob) {
        setDatabaseStructureAiJobId(backgroundJob.id)
        emitAiJobUpdate(backgroundJob)
        waitingForJob = true
        return
      }
      if (!(result.ok || result.success)) {
        setDatabaseStructureAiMessage(result.message || 'AI field generation failed.')
        window.alert(result.message || 'AI field generation failed.')
        return
      }
      const nextPayload = result.data?.crud_ai_payload
      const nextChat = result.data?.crud_ai_chat
      const nextOverride = {
        crudAiPayload: nextPayload && typeof nextPayload === 'object' ? nextPayload : note.crudAiPayload || {},
        crudAiChat: Array.isArray(nextChat) ? nextChat : note.crudAiChat || [],
      }
      setDatabaseStructureOverrides((current) => ({ ...current, [noteKey]: nextOverride }))
      setDatabaseStructureNote((current) => current ? { ...current, ...nextOverride } : { ...note, ...nextOverride })
      setDatabaseStructureAiMessage('Basic fields generated from the note and database rules. Review the draft before migration.')
    } catch (error) {
      if (error instanceof DOMException && error.name === 'AbortError') {
        setDatabaseStructureAiMessage('AI request stopped before the background job was created.')
      } else {
        setDatabaseStructureAiMessage(error instanceof Error ? error.message : 'AI field generation failed.')
        window.alert(error instanceof Error ? error.message : 'AI field generation failed.')
      }
    } finally {
      if (databaseStructureAiAbortRef.current === abortController) databaseStructureAiAbortRef.current = null
      if (!waitingForJob) {
        setDatabaseStructureAiJobId('')
        setDatabaseStructureAiBusy(false)
      }
    }
  }

  async function runPhaseAiOperationDatabase() {
    if (!phaseOperationDatabaseNote || databaseStructureAiBusy) return
    setPhaseOperationDatabaseRequested(true)
    setDatabaseStructureNote(phaseOperationDatabaseNote)
    setPhaseOperationEvents((current) => [...current, {
      id: `database-draft-started-${phaseField(phaseOperationDatabaseNote, 'noteKey')}-${Date.now()}`,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      worker: 'Database',
      text: `Preparing a draft table and fields for ${notePlannedDatabaseTable(phaseOperationDatabaseNote) || 'the planned table'}.`,
      status: 'running',
    }].slice(-20))
    await generateDatabaseStructureFields(phaseOperationDatabaseNote)
  }

  async function runPhaseAiOperationForm() {
    if (!formBuilderNote || formAiBusyNoteKey !== '') return
    const fieldNames = formBuilderRows
      .map((field) => phaseField(field, 'field_name').trim())
      .filter(Boolean)
    setPhaseOperationEvents((current) => [...current, {
      id: `form-builder-started-${phaseField(formBuilderNote, 'noteKey')}-${Date.now()}`,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', second: '2-digit' }),
      worker: 'Form Builder',
      text: `Preparing a compact form for ${formBuilderTable || 'the selected table'}.`,
      status: 'running',
    }].slice(-20))
    await runFormAiAction(formBuilderNote, `Generate a basic compact single-column form for ${formBuilderTable || 'the selected table'}. Use the current form fields${fieldNames.length > 0 ? ` (${fieldNames.join(', ')})` : ''}, concise labels, sensible controls, required validation, and a clear submit/cancel workflow. Keep it responsive and compact. Do not execute SQL or change the physical database.`)
  }

  function openDataSymbolModal(note: Record<string, any>, symbol: Record<string, any> | null = null) {
    setDataSymbolNote(note)
    setDataSymbolEditing(symbol)
    setDataSymbolType(phaseField(symbol, 'type', 'view_sql') as UiUxDataSymbolType)
    setDataSymbolTable(phaseField(symbol, 'table'))
    setDataSymbolFields(Array.isArray(symbol?.visible_fields) ? symbol.visible_fields : [])
    setDataSymbolKeyField(phaseField(symbol, 'key_field'))
    setDataSymbolKeyFields(Array.isArray(symbol?.key_fields) ? symbol.key_fields : (phaseField(symbol, 'key_field') ? [phaseField(symbol, 'key_field')] : []))
    setDataSymbolSearchFields(Array.isArray(symbol?.search_fields) ? symbol.search_fields : [])
    setDataSymbolSortField(phaseField(symbol, 'sort_field'))
    setDataSymbolSortDirection(phaseField(symbol, 'sort_direction', 'asc'))
    setDataSymbolPageSize(phaseField(symbol, 'page_size', '25'))
    setDataSymbolResultLayout(phaseField(symbol, 'result_layout', phaseField(symbol, 'type') === 'view_sql_data' ? 'vertical' : 'table') === 'vertical' ? 'vertical' : 'table')
    setDataSymbolRowActions({
      view: symbol?.row_actions?.view === true,
      edit: symbol?.row_actions?.edit === true,
      delete: symbol?.row_actions?.delete === true,
    })
    setDataSymbolShowAddRecordButton(symbol?.show_add_record_button === true)
  }

  function closeDataSymbolModal() {
    setDataSymbolNote(null)
    setDataSymbolEditing(null)
    setDataSymbolBusy(false)
  }

  function dataSymbolPayloadForNote(note: Record<string, any> | null): Array<Record<string, any>> {
    return noteDataSymbols(note)
  }

  function dataSymbolFieldsForTable(tableName = dataSymbolTable): Array<Record<string, any>> {
    return databaseStructureFields(tableName)
  }

  async function saveDataSymbol(remove = false) {
    const noteKey = phaseField(dataSymbolNote, 'noteKey')
    if (noteKey === '' || dataSymbolBusy) return

    const currentSymbols = dataSymbolPayloadForNote(dataSymbolNote)
    const symbolId = phaseField(dataSymbolEditing, 'id') || `data-symbol-${Date.now()}`
    const nextSymbol = {
      id: symbolId,
      type: dataSymbolType,
      label: dataSymbolTypeLabel(dataSymbolType),
      table: dataSymbolTable || 'NONE',
      visible_fields: dataSymbolFields,
      key_field: dataSymbolKeyField,
      key_fields: dataSymbolKeyFields,
      search_fields: dataSymbolSearchFields,
      sort_field: dataSymbolSortField,
      sort_direction: dataSymbolSortDirection,
      page_size: Number(dataSymbolPageSize) || 25,
      result_layout: dataSymbolResultLayout,
      row_actions: dataSymbolRowActions,
      show_add_record_button: dataSymbolShowAddRecordButton,
      filters: [],
      status: 'ACTIVE',
    }
    const nextSymbols = remove
      ? currentSymbols.filter((symbol) => phaseField(symbol, 'id') !== symbolId)
      : dataSymbolEditing
        ? currentSymbols.map((symbol) => phaseField(symbol, 'id') === symbolId ? nextSymbol : symbol)
        : [...currentSymbols, nextSymbol]
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'save_note_data_symbol')
    formData.set('note_key', noteKey)
    formData.set('data_symbols', JSON.stringify({ symbols: nextSymbols }))

    setDataSymbolBusy(true)
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Data symbol settings failed.')
        return
      }
      const normalizedSymbols = Array.isArray(result.data?.data_symbols?.symbols) ? result.data.data_symbols.symbols : nextSymbols
      setDataSymbolOverrides((current) => ({ ...current, [noteKey]: normalizedSymbols }))
      closeDataSymbolModal()
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Data symbol settings failed.')
    } finally {
      setDataSymbolBusy(false)
    }
  }

  async function deleteDatabaseTarget(note: Record<string, any>) {
    const noteKey = phaseField(note, 'noteKey')
    if (noteKey === '' || dataSymbolBusy) return
    if (!window.confirm('Remove this database target from the note? The note, forms, and chat history will be kept.')) return

    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'update_note_connection')
    formData.set('note_key', noteKey)
    formData.set('crud_target_table', 'NONE')
    formData.set('crud_field_name', 'NONE')
    formData.set('crud_new_table_name', '')
    formData.set('crud_new_field_name', '')

    setDataSymbolBusy(true)
    try {
      const response = await fetch('./', { method: 'POST', body: formData, headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' } })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Database target removal failed.')
        return
      }
      reloadPagePreservingScroll()
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Database target removal failed.')
    } finally {
      setDataSymbolBusy(false)
    }
  }

  function noteHasFormSymbol(note: Record<string, any>): boolean {
    const effectiveNote = effectiveFormNote(note)
    if (phaseField(effectiveNote, 'formStatus', 'ACTIVE').toUpperCase() === 'DELETED') {
      return false
    }
    const payload = effectiveNote.formAiPayload
    if (Array.isArray(payload?.form_instances) && payload.form_instances.length > 0) {
      return true
    }
    const hasPayload = typeof payload === 'object' && payload !== null && !Array.isArray(payload) && Object.keys(payload).length > 0

    return effectiveNote.formEnabled === true || phaseField(effectiveNote, 'formEnabled') === '1' || hasPayload
  }

  function formBuilderFields(note: Record<string, any> | null): Array<Record<string, any>> {
    const aiFields = note?.formAiPayload?.fields
    const aiFieldList = Array.isArray(aiFields) ? aiFields : []
    const aiByName = new Map(aiFieldList.map((field: Record<string, any>) => [phaseField(field, 'field_name'), field]))
    const presetFields = presetFormFields(note)
    if (presetFields.length === 0) return aiFieldList

    return presetFields.map((field) => {
      const aiField = aiByName.get(phaseField(field, 'field_name'))
      return aiField ? {
        ...aiField,
        field_name: phaseField(field, 'field_name'),
        data_type: phaseField(field, 'data_type'),
        source_nullable: phaseField(field, 'source_nullable'),
        source_default: phaseField(field, 'source_default'),
        source_extra: phaseField(field, 'source_extra'),
        source_comment: phaseField(field, 'source_comment'),
        source_signature: phaseField(field, 'source_signature'),
        source: 'ai',
	      } : field
	    })
	  }

  function formFieldStableKey(field: Record<string, any>, index?: number): string {
    const fieldName = phaseField(field, 'field_name')
    return fieldName !== '' ? fieldName : `field-${index ?? 0}`
  }

  function formFieldTypeLabel(type: string): string {
    return type.split('_').filter(Boolean).join(' ').toUpperCase() || 'TEXT'
  }

  function formFieldTypeHasUploadSettings(type: string): boolean {
    return /(upload|uploader|file|media|camera|capture|avatar|gallery|signature|document|video|audio|pdf|spreadsheet|csv|archive)/i.test(type)
  }

  function formFieldTypeHasLookupSettings(type: string): boolean {
    return ['select', 'multi_select', 'options', 'radio_group', 'checkbox', 'lookup', 'relation_foreign_key', 'autocomplete', 'tags'].includes(type)
  }

  function formLookupFieldNames(tableName: string): Array<string> {
    return databaseStructureFields(tableName)
      .map((field) => phaseField(field, 'fieldName'))
      .filter(Boolean)
  }

  function formLookupSummary(field: Record<string, any>): string {
    const table = phaseField(field, 'lookup_table')
    const labelField = phaseField(field, 'lookup_label_field')
    const valueField = phaseField(field, 'lookup_value_field')
    if (table === '') return ''

    return `${table}${labelField || valueField ? `: ${labelField || 'label'} / ${valueField || 'value'}` : ''}`
  }

  function formApplyOptionTextCase(value: string, mode: string): string {
    if (mode === 'uppercase') return value.toUpperCase()
    if (mode === 'lowercase') return value.toLowerCase()
    if (mode === 'proper_case') {
      return value.toLowerCase().replace(/\b[a-z]/g, (letter) => letter.toUpperCase())
    }

    return value
  }

  function previewInputType(control: string): string {
    if (control === 'password') return 'password'
    if (['email', 'url', 'tel', 'date', 'time'].includes(control)) return control
    if (['number', 'decimal', 'currency', 'rating', 'slider'].includes(control)) return 'number'
    if (control === 'datetime') return 'datetime-local'
    if (formFieldTypeHasUploadSettings(control)) return 'file'

    return 'text'
  }

  function renderFormPreviewField(field: Record<string, any>) {
    const control = phaseField(field, 'control', 'text')
    const fieldName = phaseField(field, 'field_name', 'field')
    const label = phaseField(field, 'label', formLabelForField(fieldName))
    const helpText = phaseField(field, 'help_text')
    const placeholder = phaseField(field, 'placeholder', label)
    const required = Boolean(field.required)
    const commonInputClass = 'h-9 text-sm'
    const lookupSummary = formLookupSummary(field)
    const optionLabelCase = phaseField(field, 'option_label_case', 'preserve')
    const optionValueCase = phaseField(field, 'option_value_case', 'preserve')
    const sampleLabelBase = lookupSummary ? `Sample ${phaseField(field, 'lookup_label_field', 'Label')}` : 'Sample Option'
    const sampleLabelOne = formApplyOptionTextCase(`${sampleLabelBase} 1`, optionLabelCase)
    const sampleLabelTwo = formApplyOptionTextCase(`${sampleLabelBase} 2`, optionLabelCase)
    const sampleValueOne = formApplyOptionTextCase(lookupSummary ? `sample_${phaseField(field, 'lookup_value_field', 'value')}_1` : 'sample_1', optionValueCase)
    const sampleValueTwo = formApplyOptionTextCase(lookupSummary ? `sample_${phaseField(field, 'lookup_value_field', 'value')}_2` : 'sample_2', optionValueCase)

    if (field.hidden || control === 'hidden') {
      return null
    }

    if (control === 'textarea' || control === 'rich_text' || control === 'json_code' || control === 'drawing_sketch_pad') {
      return (
        <div className="grid gap-2">
          <Label htmlFor={`preview-${fieldName}`} className="text-xs">{label}{required ? <span className="ml-1 text-orange-500">*</span> : null}</Label>
          <Textarea id={`preview-${fieldName}`} rows={control === 'drawing_sketch_pad' ? 5 : 3} placeholder={placeholder} readOnly={Boolean(field.readonly)} />
          {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
        </div>
      )
    }

    if (control === 'select' || control === 'multi_select' || control === 'options' || control === 'lookup' || control === 'relation_foreign_key' || control === 'autocomplete' || control === 'tags') {
      return (
        <div className="grid gap-2">
          <Label htmlFor={`preview-${fieldName}`} className="text-xs">{label}{required ? <span className="ml-1 text-orange-500">*</span> : null}</Label>
          <select id={`preview-${fieldName}`} className={phaseSelectClass} multiple={control === 'multi_select' || control === 'tags'} disabled={Boolean(field.readonly)}>
            <option value="">Select {label}</option>
            <option value={sampleValueOne}>{sampleLabelOne}</option>
            <option value={sampleValueTwo}>{sampleLabelTwo}</option>
          </select>
          {lookupSummary ? <p className="text-[11px] text-muted-foreground">Lookup: {lookupSummary}</p> : null}
          {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
        </div>
      )
    }

    if (control === 'checkbox' || control === 'switch' || control === 'radio_group') {
      if (lookupSummary && (control === 'checkbox' || control === 'radio_group')) {
        return (
          <div className="grid gap-2 rounded-md border bg-muted/10 p-3">
            <Label className="text-xs">{label}{required ? <span className="ml-1 text-orange-500">*</span> : null}</Label>
            <label className="flex items-center gap-2 text-sm">
              <input type={control === 'radio_group' ? 'radio' : 'checkbox'} value={sampleValueOne} disabled={Boolean(field.readonly)} />
              <span>{sampleLabelOne}</span>
            </label>
            <label className="flex items-center gap-2 text-sm">
              <input type={control === 'radio_group' ? 'radio' : 'checkbox'} value={sampleValueTwo} disabled={Boolean(field.readonly)} />
              <span>{sampleLabelTwo}</span>
            </label>
            <p className="text-[11px] text-muted-foreground">Lookup: {lookupSummary}</p>
            {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
          </div>
        )
      }

      return (
        <div className="grid gap-2 rounded-md border bg-muted/10 p-3">
          <label className="flex items-start gap-2 text-sm">
            <input type={control === 'radio_group' ? 'radio' : 'checkbox'} disabled={Boolean(field.readonly)} />
            <span>{label}{required ? <span className="ml-1 text-orange-500">*</span> : null}</span>
          </label>
          {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
        </div>
      )
    }

    if (control === 'readonly_display') {
      return (
        <div className="grid gap-2">
          <Label htmlFor={`preview-${fieldName}`} className="text-xs">{label}</Label>
          <Input id={`preview-${fieldName}`} className={commonInputClass} value={phaseField(field, 'defaultValue', 'Read-only value')} readOnly />
          {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
        </div>
      )
    }

    return (
      <div className="grid gap-2">
        <Label htmlFor={`preview-${fieldName}`} className="text-xs">{label}{required ? <span className="ml-1 text-orange-500">*</span> : null}</Label>
        <Input
          id={`preview-${fieldName}`}
          className={commonInputClass}
          type={previewInputType(control)}
          placeholder={placeholder}
          readOnly={Boolean(field.readonly)}
          multiple={control.includes('multiple') || control.includes('uploader')}
          accept={phaseField(field, 'allowedTypes')}
        />
        {helpText ? <p className="text-[11px] text-muted-foreground">{helpText}</p> : null}
      </div>
    )
  }

  function defaultFormConfirmationField(payload: Record<string, any> | null | undefined): Record<string, any> {
    const saved = payload?.confirmation_field
    if (typeof saved === 'object' && saved !== null && !Array.isArray(saved)) {
      return {
        enabled: saved.enabled !== false,
        label: phaseField(saved, 'label', 'I confirm the information is correct before submitting.'),
        required: saved.required !== false,
      }
    }

    return {
      enabled: true,
      label: 'I confirm the information is correct before submitting.',
      required: true,
    }
  }

  function defaultFormKeyFieldVariable(payload: Record<string, any> | null | undefined): Record<string, any> | null {
    const variableField = payload?.form_variables?.key_field
    return typeof variableField === 'object' && variableField !== null && !Array.isArray(variableField) ? variableField : null
  }

  function defaultFormStorageTargets(payload: Record<string, any> | null | undefined): Record<string, boolean> {
    const saved = payload?.form_storage_targets
    if (typeof saved === 'object' && saved !== null && !Array.isArray(saved)) {
      return {
        firebase: saved.firebase === true,
        mysql: saved.mysql !== false,
        json: saved.json === true,
      }
    }

    return {
      firebase: false,
      mysql: true,
      json: false,
    }
  }

  function formDatabaseTableForNote(note: Record<string, any> | null | undefined): string {
    if (!note) return ''
    return noteExistingDatabaseTable(note) || phaseField(note.formAiPayload, 'database_table') || notePlannedDatabaseTable(note)
  }

  function defaultFormSqlOperations(payload: Record<string, any> | null | undefined): Record<string, boolean> {
    const saved = payload?.form_sql_operations
    if (typeof saved === 'object' && saved !== null && !Array.isArray(saved)) {
      return {
        insertSQL: saved.insertSQL === true,
        updateSQL: saved.updateSQL === true,
        deleteSQL: saved.deleteSQL === true,
      }
    }

    return {
      insertSQL: true,
      updateSQL: true,
      deleteSQL: false,
    }
  }

  function defaultFormOperationSelection(payload: Record<string, any> | null | undefined): Record<string, boolean> {
    const saved = payload?.form_operations
    if (typeof saved === 'object' && saved !== null && !Array.isArray(saved)) {
      return {
        add: saved.add === true,
        edit: saved.edit === true,
        delete: saved.delete === true,
        viewSQL: saved.viewSQL === true,
        viewSQLData: saved.viewSQLData === true,
        searchSQL: saved.searchSQL === true,
      }
    }

    const sqlOperations = defaultFormSqlOperations(payload)
    return {
      add: sqlOperations.insertSQL === true,
      edit: sqlOperations.updateSQL === true,
      delete: sqlOperations.deleteSQL === true,
      viewSQL: false,
      viewSQLData: false,
      searchSQL: false,
    }
  }

  function singleFormOperationSelection(payload: Record<string, any> | null | undefined): Record<string, boolean> {
    const defaults = defaultFormOperationSelection(payload)
    const keys = ['add', 'edit', 'delete', 'viewSQL', 'viewSQLData', 'searchSQL']
    const selectedKey = keys.find((key) => defaults[key]) || 'add'

    return keys.reduce<Record<string, boolean>>((selection, key) => {
      selection[key] = key === selectedKey
      return selection
    }, {})
  }

  function defaultFormWorkflowConfig(payload: Record<string, any> | null | undefined): Record<string, any> {
    const saved = payload?.form_workflow
    const sourceFields = formBuilderFields({ formAiPayload: payload || {} })
    const fieldNames = sourceFields.map((field) => phaseField(field, 'field_name')).filter(Boolean)
    const savedWorkflow = typeof saved === 'object' && saved !== null && !Array.isArray(saved) ? saved : {}
    const validFieldList = (value: any, fallback: string[] = []) => {
      const values = Array.isArray(value) ? value : fallback
      return values.filter((fieldName) => typeof fieldName === 'string' && fieldNames.includes(fieldName))
    }
    const defaultKeyField = fieldNames.find((fieldName) => fieldName.endsWith('_key') || fieldName === 'id' || fieldName === 'x_Id') || ''
    const outputFields = validFieldList(savedWorkflow.output_fields, fieldNames)
    const operationSelection = singleFormOperationSelection(payload)
    const savedKeyFields = validFieldList(savedWorkflow.key_field_names)
    const legacyKeyField = phaseField(savedWorkflow, 'key_field_name')
    const defaultWorkflowKeyFields = operationSelection.viewSQLData || operationSelection.delete ? (defaultKeyField !== '' ? [defaultKeyField] : []) : []
    const keyFieldNames = savedKeyFields.length > 0
      ? savedKeyFields
      : (fieldNames.includes(legacyKeyField) ? [legacyKeyField] : defaultWorkflowKeyFields)
    const savedFilterFields = validFieldList(savedWorkflow.filter_fields, fieldNames.slice(0, 3))
    const filterFields = operationSelection.searchSQL
      ? savedFilterFields.filter((fieldName) => !keyFieldNames.includes(fieldName))
      : savedFilterFields
    const savedSearchConfigs = Array.isArray(savedWorkflow.search_field_configs)
      ? savedWorkflow.search_field_configs
      : (Array.isArray(payload?.form_variables?.search_fields) ? payload.form_variables.search_fields : [])
    const searchFieldConfigs = filterFields.map((fieldName) => {
      const sourceField = sourceFields.find((field) => phaseField(field, 'field_name') === fieldName)
      const savedConfig = savedSearchConfigs.find((config: any) => config && config.field_name === fieldName) || {}
      return {
        field_name: fieldName,
        control: phaseField(savedConfig, 'control', phaseField(sourceField, 'control', formControlForField(fieldName, phaseField(sourceField, 'data_type')))),
        variable_name: phaseField(savedConfig, 'variable_name', `search_${fieldName}`),
        operator: phaseField(savedConfig, 'operator', 'contains'),
        label: phaseField(savedConfig, 'label', phaseField(sourceField, 'label', formLabelForField(fieldName))),
        placeholder: phaseField(savedConfig, 'placeholder'),
        default_value: phaseField(savedConfig, 'default_value'),
        required: savedConfig.required === true,
        lookup_table: phaseField(savedConfig, 'lookup_table', phaseField(sourceField, 'lookup_table')),
        lookup_label_field: phaseField(savedConfig, 'lookup_label_field', phaseField(sourceField, 'lookup_label_field')),
        lookup_value_field: phaseField(savedConfig, 'lookup_value_field', phaseField(sourceField, 'lookup_value_field')),
        option_label_case: phaseField(savedConfig, 'option_label_case', phaseField(sourceField, 'option_label_case', 'preserve')),
        option_value_case: phaseField(savedConfig, 'option_value_case', phaseField(sourceField, 'option_value_case', 'preserve')),
      }
    })
    const savedResultLayout = savedWorkflow.result_layout === 'vertical' || savedWorkflow.result_layout === 'table' ? savedWorkflow.result_layout : ''

    return {
      key_field_name: keyFieldNames[0] || '',
      key_field_names: keyFieldNames,
      filter_fields: filterFields,
      search_field_configs: searchFieldConfigs,
      output_fields: outputFields.length > 0 ? outputFields : fieldNames,
      delete_display_fields: validFieldList(savedWorkflow.delete_display_fields, outputFields.length > 0 ? outputFields : fieldNames),
      row_actions: {
        view: savedWorkflow.row_actions?.view === true,
        edit: savedWorkflow.row_actions?.edit === true,
        delete: savedWorkflow.row_actions?.delete === true,
      },
      show_add_record_button: savedWorkflow.show_add_record_button === true,
      result_layout: savedResultLayout || (operationSelection.viewSQLData ? 'vertical' : 'table'),
      confirmation_required: savedWorkflow.confirmation_required !== false,
      confirmation_message: phaseField(savedWorkflow, 'confirmation_message', 'Confirm this action before continuing.'),
      submit_label: phaseField(savedWorkflow, 'submit_label', formWorkflowSubmitLabel(operationSelection)),
    }
  }

  function formWorkflowSubmitLabel(selection: Record<string, boolean>): string {
    if (selection.add) return 'Add Record'
    if (selection.edit) return 'Save Changes'
    if (selection.delete) return 'Delete Record'
    if (selection.searchSQL) return 'Search Records'
    if (selection.viewSQLData) return 'View Record'
    if (selection.viewSQL) return 'View Records'

    return 'Submit'
  }

  function formResultMessageDefault(selection: Record<string, boolean>): string {
    if (selection.add || selection.edit || selection.delete) return 'Database has been Updated'
    if (selection.searchSQL) return 'Search completed successfully.'
    if (selection.viewSQLData) return 'Record loaded successfully.'
    if (selection.viewSQL) return 'Records loaded successfully.'

    return 'Operation completed successfully.'
  }

  function formResultMessageConfig(payload: Record<string, any> | null | undefined, selection: Record<string, boolean>): { enabled: boolean; message: string; mode: 'toast' | 'modal' } {
    const mode = phaseField(payload, 'form_result_message_mode', 'toast') === 'modal' ? 'modal' : 'toast'

    return {
      enabled: payload?.form_result_message_enabled !== false,
      message: phaseField(payload, 'form_result_message', formResultMessageDefault(selection)),
      mode,
    }
  }

  function formCapabilityLabel(payload: Record<string, any> | null | undefined): string {
    const selection = defaultFormOperationSelection(payload)
    const labels = [
      ['add', 'ADD'],
      ['edit', 'EDIT'],
      ['delete', 'DELETE'],
      ['viewSQL', 'VIEW DATA'],
      ['viewSQLData', 'VIEW RECORD'],
      ['searchSQL', 'SEARCH'],
    ] as const
    const activeLabels = labels.filter(([key]) => selection[key]).map(([, label]) => label)

    return activeLabels.length > 0 ? activeLabels.join(' / ') : 'FORM'
  }

  function formInstancesForNote(note: Record<string, any> | null | undefined): Array<Record<string, any>> {
    const saved = note?.formAiPayload?.form_instances
    if (Array.isArray(saved) && saved.length > 0) {
      return saved.filter((instance) => typeof instance === 'object' && instance !== null && !Array.isArray(instance))
    }
    if (noteHasFormSymbol(note || {})) {
      return [{
        ...(note?.formAiPayload || {}),
        form_id: 'form-legacy',
      }]
    }
    return []
  }

  function formOperationPayload(selection: Record<string, boolean>): Record<string, any> {
    return {
      form_operations: {
        add: selection.add === true,
        edit: selection.edit === true,
        delete: selection.delete === true,
        viewSQL: selection.viewSQL === true,
        viewSQLData: selection.viewSQLData === true,
        searchSQL: selection.searchSQL === true,
      },
      form_sql_operations: {
        insertSQL: selection.add === true,
        updateSQL: selection.edit === true,
        deleteSQL: selection.delete === true,
      },
    }
  }

  function defaultFormQueryFields(payload: Record<string, any> | null | undefined): Array<Record<string, any>> {
    const queryFields = payload?.form_variables?.query_fields
    return Array.isArray(queryFields) ? queryFields
      .filter((field) => typeof field === 'object' && field !== null && !Array.isArray(field))
      .map((field) => ({
        ...field,
        value_remain_unchanged: field.value_remain_unchanged !== false,
      })) : []
  }

  function defaultFormLayoutRows(payload: Record<string, any> | null | undefined): Array<Record<string, any>> {
    const rows = payload?.builder_layout?.rows
    return Array.isArray(rows) ? rows.map((row, index) => ({
      id: phaseField(row, 'id', `row-${Date.now()}-${index}`),
      columns: Math.min(12, Math.max(1, Number(row.columns) || 12)),
      fields: Array.isArray(row.fields) ? row.fields : [],
    })) : []
  }

  function flatFormLayoutFields(rows: Array<Record<string, any>>): Array<Record<string, any>> {
    return rows.flatMap((row) => Array.isArray(row.fields) ? row.fields : [])
  }

  function formVariableFields(keyField: Record<string, any> | null, queryFields: Array<Record<string, any>> = []): Array<Record<string, any>> {
    return [
      ...(keyField ? [keyField] : []),
      ...queryFields,
    ]
  }

  function usedFormFieldNames(rows: Array<Record<string, any>>, keyField: Record<string, any> | null, queryFields: Array<Record<string, any>> = []): Set<string> {
    return new Set([...flatFormLayoutFields(rows), ...formVariableFields(keyField, queryFields)].map((field) => phaseField(field, 'field_name')).filter(Boolean))
  }

  function formLayoutFieldFromSource(field: Record<string, any>): Record<string, any> {
    return {
      ...field,
      id: `field-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      label: phaseField(field, 'label', formLabelForField(phaseField(field, 'field_name'))),
      control: phaseField(field, 'control', 'text'),
      isKeyField: false,
      isValueSource: false,
      readonly: false,
      hidden: false,
      searchable: false,
      displayField: false,
    }
  }

  function formLayoutFieldFromSearchConfig(config: Record<string, any>, sourceFields: Array<Record<string, any>> = formBuilderRows): Record<string, any> {
    const fieldName = phaseField(config, 'field_name')
    const sourceField = sourceFields.find((field) => phaseField(field, 'field_name') === fieldName) || { field_name: fieldName }

    return formLayoutFieldFromSource({
      ...sourceField,
      ...config,
      field_name: fieldName,
      label: phaseField(config, 'label', phaseField(sourceField, 'label', formLabelForField(fieldName))),
      control: phaseField(config, 'control', phaseField(sourceField, 'control', 'text')),
      placeholder: phaseField(config, 'placeholder', phaseField(sourceField, 'placeholder')),
      defaultValue: phaseField(config, 'default_value', phaseField(sourceField, 'defaultValue')),
      required: config.required === true,
    })
  }

  function formLayoutRowsWithSearchFields(rows: Array<Record<string, any>>, fieldNames: string[], sourceFields: Array<Record<string, any>> = formBuilderRows, searchConfigs: Array<Record<string, any>> = [], removeUnselected = false): Array<Record<string, any>> {
    const selectedNames = fieldNames.filter(Boolean)
    const selectedSet = new Set(selectedNames)
    const preparedRows: Array<Record<string, any>> = removeUnselected
      ? rows.map((row) => ({
          ...row,
          fields: (Array.isArray(row.fields) ? row.fields : []).filter((field) => selectedSet.has(phaseField(field, 'field_name'))),
        }))
      : rows
    const existingNames = new Set(flatFormLayoutFields(preparedRows).map((field) => phaseField(field, 'field_name')).filter(Boolean))
    const missingNames = selectedNames.filter((fieldName) => !existingNames.has(fieldName))
    if (missingNames.length === 0) return preparedRows

    const nextRows: Array<Record<string, any>> = preparedRows.map((row) => ({ ...row, fields: Array.isArray(row.fields) ? [...row.fields] : [] }))
    missingNames.forEach((fieldName) => {
      const sourceField = sourceFields.find((field) => phaseField(field, 'field_name') === fieldName)
      const savedConfig = searchConfigs.find((item) => phaseField(item, 'field_name') === fieldName) || {}
      const config = {
        field_name: fieldName,
        label: phaseField(sourceField, 'label', formLabelForField(fieldName)),
        control: phaseField(sourceField, 'control', formControlForField(fieldName, phaseField(sourceField, 'data_type'))),
        variable_name: `search_${fieldName}`,
        required: false,
        ...savedConfig,
      }
      let targetIndex = nextRows.findIndex((row) => {
        const columns = Math.min(12, Math.max(1, Number(row.columns) || 12))
        const capacity = Math.max(1, Math.floor(12 / columns))
        return row.fields.length < capacity
      })
      if (targetIndex < 0) {
        targetIndex = nextRows.length
        nextRows.push({
          id: `search-row-${Date.now()}-${Math.random().toString(16).slice(2)}`,
          columns: 6,
          fields: [],
        })
      }
      nextRows[targetIndex].fields.push(formLayoutFieldFromSearchConfig(config, sourceFields))
    })

    return nextRows
  }

  function orderedFormBuilderFields(note: Record<string, any> | null): Array<Record<string, any>> {
    const fields = formBuilderFields(note)
    if (formFieldOrder.length === 0) return fields
    const byKey = new Map(fields.map((field, index) => [formFieldStableKey(field, index), field]))
    const ordered = formFieldOrder.map((key) => byKey.get(key)).filter(Boolean) as Array<Record<string, any>>
    const included = new Set(formFieldOrder)
    fields.forEach((field, index) => {
      const key = formFieldStableKey(field, index)
      if (!included.has(key)) ordered.push(field)
    })

    return ordered
  }

  function formQueryCreateModeLabel(mode: string): string {
    if (mode === 'manual') return 'Manual Default'
    if (mode === 'automatic') return 'Automatic Value'

    return 'Blank'
  }

  function formQueryAutomaticValueLabel(value: string): string {
    const labels: Record<string, string> = {
      auto_increment: 'AUTO INCREMENT',
      current_timestamp: 'CURRENT TIMESTAMP',
      current_user_key: 'CURRENT USER KEY',
      current_user_login: 'CURRENT USER LOGIN',
      empty_string: 'EMPTY STRING',
      firebase_server_timestamp: 'FIREBASE SERVER TIMESTAMP',
      uuid: 'UUID',
    }

    return labels[value] || value.toUpperCase()
  }

  function showFormBuilderModal(nextNote: Record<string, any>, instanceId = '') {
    const instances = formInstancesForNote(nextNote)
    const selectedInstance = instanceId !== '' ? instances.find((instance) => phaseField(instance, 'form_id') === instanceId) : null
    const payloadSource = selectedInstance || nextNote.formAiPayload
    const payload = typeof payloadSource === 'object'
      && payloadSource !== null
      && !Array.isArray(payloadSource)
      ? payloadSource
      : {}
    const builderNote = { ...nextNote, formAiPayload: payload }
    setFormBuilderInstanceId(selectedInstance ? phaseField(selectedInstance, 'form_id') : instanceId)
    setFormBuilderNote(builderNote)
    setFormPreviewResultVisible(false)
    setFormFieldOrder(formBuilderFields(builderNote).map((field, index) => formFieldStableKey(field, index)))
    const workflowConfig = defaultFormWorkflowConfig(payload)
    const sourceFields = formBuilderFields(builderNote)
    const initialLayoutRows = defaultFormLayoutRows(payload)
    const operationSelection = singleFormOperationSelection(payload)
    setFormLayoutRows(operationSelection.searchSQL
      ? formLayoutRowsWithSearchFields(initialLayoutRows, workflowConfig.filter_fields, sourceFields, workflowConfig.search_field_configs, true)
      : initialLayoutRows)
    setFormKeyFieldVariable(defaultFormKeyFieldVariable(payload))
    setFormQueryFields(defaultFormQueryFields(payload))
    setFormQueryFieldToAdd('')
    setFormConfirmationField(defaultFormConfirmationField(payload))
    setFormBuilderOperationSelection(operationSelection)
    setFormWorkflowConfig(workflowConfig)
    setFormWorkflowAutoSavePending(false)
  }

  function quickBuildFormBuilder() {
    if (!formBuilderNote || formSaveBusyNoteKey !== '') return
    const sourceFields = formBuilderFields(formBuilderNote)
      .filter((field) => phaseField(field, 'field_name') !== '' && !isInternalFormField(phaseField(field, 'field_name')))
    if (sourceFields.length === 0) {
      window.alert('No database fields are available for this form.')
      return
    }

    const existingNames = usedFormFieldNames(formLayoutRows, formKeyFieldVariable, formQueryFields)
    const missingFields = sourceFields.filter((field) => !existingNames.has(phaseField(field, 'field_name')))
    const nextRows = formLayoutRows.length > 0
      ? formLayoutRowsWithSearchFields(formLayoutRows, missingFields.map((field) => phaseField(field, 'field_name')), sourceFields)
      : sourceFields.map((field, index) => ({
          id: `quick-build-row-${Date.now()}-${index}`,
          columns: 12,
          fields: [formLayoutFieldFromSource(field)],
        }))

    setFormLayoutRows(nextRows)
    setFormFieldOrder(sourceFields.map((field, index) => formFieldStableKey(field, index)))
    void saveFormBuilderLayout(formBuilderNote, { layoutRows: nextRows })
  }

  function toggleFormWorkflowField(listKey: 'filter_fields' | 'output_fields' | 'delete_display_fields', fieldName: string) {
    const currentValues = Array.isArray(formWorkflowConfig[listKey]) ? formWorkflowConfig[listKey] : []
    const nextValues = currentValues.includes(fieldName) ? currentValues.filter((value: string) => value !== fieldName) : [...currentValues, fieldName]
    setFormWorkflowConfig((current) => {
      const values = Array.isArray(current[listKey]) ? current[listKey] : []
      const nextValues = values.includes(fieldName) ? values.filter((value: string) => value !== fieldName) : [...values, fieldName]
      return {
        ...current,
        [listKey]: nextValues,
        ...(listKey === 'filter_fields' ? {
          search_field_configs: nextValues.map((value: string) => {
            const existing = (Array.isArray(current.search_field_configs) ? current.search_field_configs : []).find((config: Record<string, any>) => phaseField(config, 'field_name') === value)
            return existing || {
              field_name: value,
              control: phaseField(formBuilderRows.find((field) => phaseField(field, 'field_name') === value), 'control', formControlForField(value, phaseField(formBuilderRows.find((field) => phaseField(field, 'field_name') === value), 'data_type'))),
              variable_name: `search_${value}`,
              operator: 'contains',
              label: formLabelForField(value),
              placeholder: '',
              default_value: '',
              required: false,
              lookup_table: '',
              lookup_label_field: '',
              lookup_value_field: '',
              option_label_case: 'preserve',
              option_value_case: 'preserve',
            }
          }),
        } : {}),
      }
    })
    if (formBuilderOperationSelection.searchSQL && listKey === 'filter_fields') {
      const removedFields = currentValues.filter((value: string) => !nextValues.includes(value))
      setFormLayoutRows((current) => formLayoutRowsWithSearchFields(
        current.map((row) => ({
          ...row,
          fields: (Array.isArray(row.fields) ? row.fields : []).filter((field) => !removedFields.includes(phaseField(field, 'field_name'))),
        })),
        nextValues,
        formBuilderRows,
        Array.isArray(formWorkflowConfig.search_field_configs) ? formWorkflowConfig.search_field_configs : [],
      ))
    }
    if (formBuilderOperationSelection.searchSQL && (listKey === 'filter_fields' || listKey === 'output_fields')) {
      setFormWorkflowAutoSavePending(true)
    }
  }

  function updateSearchFieldConfig(fieldName: string, changes: Record<string, any>) {
    setFormWorkflowConfig((current) => ({
      ...current,
      search_field_configs: (Array.isArray(current.search_field_configs) ? current.search_field_configs : []).map((config: Record<string, any>) => phaseField(config, 'field_name') === fieldName ? { ...config, ...changes } : config),
    }))
    setFormLayoutRows((current) => current.map((row) => ({
      ...row,
      fields: (Array.isArray(row.fields) ? row.fields : []).map((field) => {
        if (phaseField(field, 'field_name') !== fieldName) return field
        const currentConfig = (Array.isArray(formWorkflowConfig.search_field_configs) ? formWorkflowConfig.search_field_configs : []).find((config: Record<string, any>) => phaseField(config, 'field_name') === fieldName) || { field_name: fieldName }
        const nextField = formLayoutFieldFromSearchConfig({ ...currentConfig, ...changes }, formBuilderRows)
        return { ...nextField, id: phaseField(field, 'id', nextField.id) }
      }),
    })))
    if (formBuilderOperationSelection.searchSQL) {
      setFormWorkflowAutoSavePending(true)
    }
  }

  function setFormWorkflowKeyField(fieldName: string) {
    setFormWorkflowConfig((current) => ({ ...current, key_field_name: fieldName, key_field_names: fieldName === '' ? [] : [fieldName] }))
    const sourceField = formBuilderRows.find((field) => phaseField(field, 'field_name') === fieldName)
    setFormKeyFieldVariable(sourceField ? { ...sourceField, isKeyField: true, isValueSource: true } : null)
  }

  function toggleFormWorkflowKeyField(fieldName: string) {
    setFormWorkflowConfig((current) => {
      const currentNames = Array.isArray(current.key_field_names) && current.key_field_names.length > 0
        ? current.key_field_names
        : (typeof current.key_field_name === 'string' && current.key_field_name !== '' ? [current.key_field_name] : [])
      const nextNames = currentNames.includes(fieldName)
        ? currentNames.filter((value: string) => value !== fieldName)
        : [...currentNames, fieldName]
      return {
        ...current,
        key_field_name: nextNames[0] || '',
        key_field_names: nextNames,
        filter_fields: formBuilderOperationSelection.searchSQL
          ? (Array.isArray(current.filter_fields) ? current.filter_fields : []).filter((value: string) => !nextNames.includes(value))
          : current.filter_fields,
        search_field_configs: formBuilderOperationSelection.searchSQL
          ? (Array.isArray(current.search_field_configs) ? current.search_field_configs : []).filter((config: Record<string, any>) => !nextNames.includes(phaseField(config, 'field_name')))
          : current.search_field_configs,
      }
    })
    if (formBuilderOperationSelection.searchSQL) {
      setFormWorkflowAutoSavePending(true)
    }
    const firstKeyField = formBuilderRows.find((field) => phaseField(field, 'field_name') === fieldName)
    if (firstKeyField) {
      setFormKeyFieldVariable((current) => current || { ...firstKeyField, isKeyField: true, isValueSource: true })
    }
  }

  function openFormBuilderModal(nextNote: Record<string, any>, instanceId = '') {
    showFormBuilderModal(effectiveFormNote(nextNote), instanceId)
  }

  function uiUxFlowAiPlanPhases(plan: Record<string, any> | null | undefined): Array<Record<string, any>> {
    return Array.isArray(plan?.phases) ? plan.phases : []
  }

  function uiUxFlowAiPlanChat(plan: Record<string, any> | null | undefined): Array<Record<string, any>> {
    return Array.isArray(plan?.chat) ? plan.chat : []
  }

  function uiUxFlowSnapshot(): Record<string, any> {
    return {
      flow_key: flowKey,
      flow_label: flowLabel,
      section_key: sectionKey,
      section_label: phaseField(selectedSection, 'label', sectionKey),
      section_title: phaseField(selectedSection, 'title', phaseField(selectedSection, 'label', sectionKey)),
      section_description: phaseField(selectedSection, 'description'),
      groups,
      source_setting: phaseField(phaseData?.uiUxFlow, 'sourceSetting', 'UI_UX_FLOW_JSON'),
    }
  }

  function noteTaskCodeFromPlanNote(note: Record<string, any>): string {
    const noteCode = phaseField(note, 'note_code')
    return noteCode.replace(/-N\d+$/i, '')
  }

  function uiUxFlowAiPhaseNotes(phase: Record<string, any> | null | undefined): Array<Record<string, any>> {
    return Array.isArray(phase?.notes) ? phase.notes : []
  }

  function uiUxFlowAiTaskCodesForPhase(phase: Record<string, any> | null | undefined): Array<string> {
    return Array.from(new Set(uiUxFlowAiPhaseNotes(phase).map((note) => noteTaskCodeFromPlanNote(note)).filter(Boolean)))
  }

  function focusUiUxFlowAiPhaseCode(phaseCode: string) {
    setUiUxFlowAiPanelVisible(true)
    setUiUxFlowAiFocusPhaseCode(phaseCode || 'ALL')
    setUiUxFlowAiFocusTaskCode('NONE')
    setUiUxFlowAiFocusNoteKey('NONE')
  }

  function focusUiUxFlowAiTaskCode(phaseCode: string, taskCode: string) {
    setUiUxFlowAiPanelVisible(true)
    setUiUxFlowAiFocusPhaseCode(phaseCode || 'ALL')
    setUiUxFlowAiFocusTaskCode(taskCode || 'NONE')
    setUiUxFlowAiFocusNoteKey('NONE')
    window.setTimeout(() => document.getElementById('ui-ux-ai-notes-workspace')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 0)
  }

  function persistUiUxNoteSelection(noteKey: string) {
    if (typeof window === 'undefined') return
    const url = new URL(window.location.href)
    if (noteKey === '') url.searchParams.delete('ui_ux_note')
    else url.searchParams.set('ui_ux_note', noteKey)
    window.history.pushState({}, '', url)
  }

  function uiUxFlowAiCurrentFocusContext(): Record<string, string> {
    return {
      focus_scope: uiUxFlowAiFocusScope,
      phase_code: uiUxFlowAiSelectedPhaseCode,
      task_code: uiUxFlowAiSelectedTaskCode,
      note_key: phaseField(uiUxFlowAiSelectedNote, 'note_key'),
      note_code: phaseField(uiUxFlowAiSelectedNote, 'note_code') || (uiUxFlowAiFocusScope === 'note' ? uiUxFlowAiFocusNoteKey : ''),
      focus_label: uiUxFlowAiFocusLabel,
      focus_prompt: uiUxFlowAiFocusPrompt,
    }
  }

  function uiUxFlowAiQueuedMessageMatchesFocus(message: Record<string, any>): boolean {
    const scope = phaseField(message, 'focus_scope')
    if (scope !== uiUxFlowAiFocusScope) return false
    if (scope === 'flow') return true
    if (scope === 'phase') return phaseField(message, 'phase_code') === uiUxFlowAiSelectedPhaseCode
    if (scope === 'task') return phaseField(message, 'task_code') === uiUxFlowAiSelectedTaskCode
    if (scope === 'note') {
      return phaseField(message, 'note_key') === phaseField(uiUxFlowAiSelectedNote, 'note_key')
        || phaseField(message, 'note_code') === phaseField(uiUxFlowAiSelectedNote, 'note_code')
        || phaseField(message, 'note_key') === uiUxFlowAiFocusNoteKey
    }

    return false
  }

  function buildUiUxFlowFocusedBuilderPrompt(mode: 'summary' | 'checklist'): string {
    const modeInstruction = mode === 'checklist'
      ? 'Build or update only the unfinished checklist work for this selected UI - UX scope. Treat unchecked or unresolved checklist items as the implementation target.'
      : 'Build or update the selected UI - UX scope from its summary, prompt, notes, database links, form symbols, and current plan.'

    return [
      '# BuilderX UI - UX Focused Builder Request',
      '',
      `Focus: ${uiUxFlowAiFocusLabel}`,
      `Scope: ${uiUxFlowAiFocusScope}`,
      `Mode: ${mode}`,
      '',
      modeInstruction,
      '',
      '## Focused Prompt',
      uiUxFlowAiFocusPrompt,
      '',
      '## Focus Context JSON',
      '```json',
      JSON.stringify(uiUxFlowAiCurrentFocusContext(), null, 2),
      '```',
      '',
      '## Full Memory Pack',
      buildUiUxFlowMemoryPackPrompt(),
    ].join('\n')
  }

  function uiUxFlowAiNotePrompt(phase: Record<string, any>, note: Record<string, any>): string {
    const noteCode = phaseField(note, 'note_code', 'selected note')
    return phaseField(note, 'prompt') || `AI Read docs/project/project-flow.md and process ${noteCode} in ${phaseField(phase, 'phase_code', 'this phase')}.`
  }

  function uiUxFlowAiTaskPrompt(phase: Record<string, any>, taskCode: string): string {
    const notes = (Array.isArray(phase.notes) ? phase.notes : []).filter((note: Record<string, any>) => noteTaskCodeFromPlanNote(note) === taskCode)
    return [
      `AI Read docs/project/project-flow.md and process all notes in ${taskCode}.`,
      ...notes.map((note: Record<string, any>) => `- ${phaseField(note, 'note_code')}: ${phaseField(note, 'prompt', phaseField(note, 'summary'))}`),
    ].join('\n')
  }

  function uiUxFlowAiPhasePrompt(phase: Record<string, any>): string {
    const phaseCode = phaseField(phase, 'phase_code', 'this phase')
    return [
      `AI Read docs/project/project-flow.md and process the full ${phaseCode} phase.`,
      `Phase purpose: ${phaseField(phase, 'phase_summary', phaseField(phase, 'phase_title'))}`,
      'Checklist:',
      ...(Array.isArray(phase.checklist) ? phase.checklist : []).map((item: string) => `- ${item}`),
      'Notes:',
      ...(Array.isArray(phase.notes) ? phase.notes : []).map((note: Record<string, any>) => `- ${phaseField(note, 'note_code')}: ${phaseField(note, 'prompt', phaseField(note, 'summary'))}`),
    ].join('\n')
  }

  function uiUxFlowBuildStats(): Record<string, number> {
    let subphases = 0
    let notes = 0
    let databaseLinks = 0
    let formSymbols = 0
    groups.forEach((group) => {
      const groupSubphases = Array.isArray(group.subphases) ? group.subphases : []
      subphases += groupSubphases.length
      groupSubphases.forEach((subphase: Record<string, any>) => {
        const subphaseNotes = Array.isArray(subphase.notes) ? subphase.notes : []
        notes += subphaseNotes.length
        subphaseNotes.forEach((note: Record<string, any>) => {
          if (noteCrudTarget(note) !== 'NONE') {
            databaseLinks += 1
          }
          if (phaseNumber(note, 'formEnabled') === 1 && phaseField(note, 'formStatus', 'ACTIVE') !== 'DELETED') {
            formSymbols += 1
          }
        })
      })
    })

    return {
      phases: groups.length,
      subphases,
      notes,
      databaseLinks,
      formSymbols,
      aiPlanPhases: uiUxFlowAiPhases.length,
    }
  }

  function buildUiUxFlowMemoryPackPrompt(): string {
    const snapshot = uiUxFlowSnapshot()
    const stats = uiUxFlowBuildStats()
    const plan = uiUxFlowAiPhases.length > 0 ? uiUxFlowAiPlan : {
      summary: 'No AI plan has been generated yet; use the live UI - UX snapshot as the source of truth.',
      overall_prompt: uiUxFlowAiOverallPrompt,
      phases: [],
    }

    return [
      `# BuilderX UI - UX Flow Build Memory Pack`,
      '',
      `Flow: ${flowLabel} (${flowKey})`,
      `Section: ${phaseField(selectedSection, 'label', sectionKey)} (${sectionKey})`,
      `Source setting: ${phaseField(phaseData?.uiUxFlow, 'sourceSetting', 'UI_UX_FLOW_JSON')}`,
      '',
      '## Codex Chat Instruction',
      'You are Codex Chat working inside this BuilderX repository.',
      'Read `docs/project/flow.md`, `docs/project/project-flow.md`, and the local source code before editing.',
      'Use this Memory Pack to remember the intended UI - UX process, linked database/form symbols, and AI-generated planning.',
      'Implement only the scoped functionality represented by this current flow/section. Preserve existing BuilderX conventions, soft-delete behavior, modal confirmations, naming rules, and validation patterns.',
      'After coding, run the relevant PHP lint, frontend build, and a browser smoke check where applicable. Return changed files and validation results.',
      '',
      '## Readiness Snapshot',
      `- Phases: ${stats.phases}`,
      `- Subphases: ${stats.subphases}`,
      `- Notes: ${stats.notes}`,
      `- Database links: ${stats.databaseLinks}`,
      `- Form symbols: ${stats.formSymbols}`,
      `- AI planned phases: ${stats.aiPlanPhases}`,
      '',
      '## Overall Prompt',
      uiUxFlowAiOverallPrompt,
      '',
      '## Current AI Plan JSON',
      '```json',
      JSON.stringify(plan, null, 2),
      '```',
      '',
      '## Live UI - UX Snapshot JSON',
      '```json',
      JSON.stringify(snapshot, null, 2),
      '```',
    ].join('\n')
  }

  async function copyUiUxFlowAiText(key: string, text: string) {
    try {
      await navigator.clipboard?.writeText(text)
      setUiUxFlowAiCopiedKey(key)
      window.setTimeout(() => setUiUxFlowAiCopiedKey(''), 1200)
    } catch {
      const textarea = document.createElement('textarea')
      textarea.value = text
      textarea.style.position = 'fixed'
      textarea.style.opacity = '0'
      document.body.appendChild(textarea)
      textarea.select()
      document.execCommand('copy')
      document.body.removeChild(textarea)
      setUiUxFlowAiCopiedKey(key)
      window.setTimeout(() => setUiUxFlowAiCopiedKey(''), 1200)
    }
  }

  async function submitUiUxFlowAiPlanRequest(
    action: 'run_ui_ux_flow_ai_plan' | 'respond_ui_ux_flow_ai_plan',
    userMessage = '',
    focusContext: Record<string, any> = uiUxFlowAiCurrentFocusContext(),
    showAlert = true,
  ): Promise<boolean> {
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', action)
    formData.set('ui_ux_flow', flowKey)
    formData.set('ui_ux_section', sectionKey)
    formData.set('ui_ux_snapshot', JSON.stringify(uiUxFlowSnapshot()))
    formData.set('focus_scope', phaseField(focusContext, 'focus_scope', 'flow'))
    formData.set('focus_phase_code', phaseField(focusContext, 'phase_code'))
    formData.set('focus_task_code', phaseField(focusContext, 'task_code'))
    formData.set('focus_note_key', phaseField(focusContext, 'note_key'))
    formData.set('focus_note_code', phaseField(focusContext, 'note_code'))
    formData.set('focus_label', phaseField(focusContext, 'focus_label'))
    formData.set('focus_prompt', phaseField(focusContext, 'focus_prompt'))
    formData.set('user_message', userMessage)
    const chatAttachmentFiles = Array.isArray(focusContext.chat_attachment_files) ? focusContext.chat_attachment_files : []
    chatAttachmentFiles.forEach((file: File) => formData.append('chat_images[]', file))

    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        if (showAlert) window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return false
      }
      const result = JSON.parse(rawText)
      if (maybeHandleAiBackgroundJobResult(result)) {
        return true
      }
      if (!(result.ok || result.success)) {
        if (showAlert) window.alert(result.message || 'UI - UX flow AI planning failed.')
        return false
      }
      const nextPlan = result.data?.ui_ux_flow_ai_plan || {}
      setUiUxFlowAiPlan(nextPlan)
      if (phaseData) {
          phaseData.uiUxFlowAiPlan = nextPlan
      }
      return true
    } catch (error) {
      if (showAlert) window.alert(error instanceof Error ? error.message : 'UI - UX flow AI planning failed.')
      return false
    }
  }

  async function runUiUxFlowAiPlan(action: 'run_ui_ux_flow_ai_plan' | 'respond_ui_ux_flow_ai_plan', userMessage = '') {
    if (uiUxFlowAiBusy || uiUxFlowAiJobProcessing) return

    setUiUxFlowAiBusy(true)
    try {
      const success = await submitUiUxFlowAiPlanRequest(action, userMessage, uiUxFlowAiCurrentFocusContext(), true)
      if (success) {
        setUiUxFlowAiChatMessage('')
      }
    } finally {
      setUiUxFlowAiBusy(false)
    }
  }

  async function runUiUxBatchTextPolish() {
    if (uiUxBatchPolishBusy || uiUxFlowAiJobProcessing || groups.length === 0) return

    setUiUxBatchPolishBusy(true)
    try {
      const snapshot = {
        ...uiUxFlowSnapshot(),
        page_url: window.location.href,
        active_view: 'flow',
        delivery_target: 'vscode_active_codex_chat',
      }
      const builderPrompt = buildUiUxFlowBatchPolishAiChatPrompt(snapshot)
      const estimatedPromptTokens = Math.max(1, Math.ceil(builderPrompt.length / 4))
      setUiUxFlowAiBusy(true)
      setNoteChatSendStatus(`Preparing text polish for Codex Chat (~${estimatedPromptTokens.toLocaleString()} tokens)…`)

      const contextForm = new FormData()
      contextForm.set('action', 'prepare_visual_codex_handoff')
      contextForm.set('handoff_mode', 'general')
      contextForm.set('csrf', phaseData?.csrf || '')
      contextForm.set('builder_prompt', builderPrompt)
      contextForm.set('annotation_snapshot', JSON.stringify(snapshot))

      const contextResponse = await fetch('./', {
        method: 'POST',
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
        body: contextForm,
      })
      const contextResult = await contextResponse.json()
      if (!contextResponse.ok || contextResult?.success === false || contextResult?.ok === false) {
        throw new Error(contextResult?.message || 'BuilderX could not prepare the Codex Chat request.')
      }

      const handoff = contextResult?.visual_codex_handoff ?? contextResult?.data?.visual_codex_handoff
      const ideCommand = typeof handoff?.ide_command === 'string' ? handoff.ide_command : ''
      if (ideCommand === '') throw new Error('BuilderX prepared the text polish request but did not return the Codex Chat command.')

      const messageId = crypto.randomUUID()
      await waitForVsCodeAiIdle(messageId)
      setNoteChatSendStatus(`Sending text polish to Codex Chat (~${estimatedPromptTokens.toLocaleString()} tokens)…`)
      const bridgeResponse = await sendCodexHandoff(codexHandoffFromPrepared(handoff, ideCommand), ideCommand)
      const bridgeResult = await bridgeResponse.json()
      if (!bridgeResponse.ok || bridgeResult?.ok !== true) {
        throw new Error(bridgeResult?.message || 'The VS Code bridge did not accept the text polish request.')
      }

      const requestId = typeof bridgeResult?.delivery?.request_id === 'string' ? bridgeResult.delivery.request_id : ''
      if (requestId === '') throw new Error('The VS Code bridge did not return a tracked text polish request ID.')
      const aiReply = await waitForVsCodeAiCompletion(messageId, requestId)

      const applyForm = new FormData()
      applyForm.set('action', 'apply_ui_ux_flow_batch_text_polish')
      applyForm.set('csrf', phaseData?.csrf || '')
      applyForm.set('ui_ux_flow', flowKey)
      applyForm.set('ui_ux_section', sectionKey)
      applyForm.set('ui_ux_snapshot', JSON.stringify(snapshot))
      applyForm.set('ui_ux_result', aiReply)
      setNoteChatSendStatus('Codex Chat returned corrections. Applying the validated text changes…')
      const applyResponse = await fetch('./', {
        method: 'POST',
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
        body: applyForm,
      })
      const applyResult = await applyResponse.json()
      if (!applyResponse.ok || applyResult?.success === false || applyResult?.ok === false) {
        throw new Error(applyResult?.message || 'BuilderX could not apply the validated text corrections.')
      }
      const nextPayload = applyResult?.data?.ui_ux_flow_payload
      if (nextPayload && typeof nextPayload === 'object' && !Array.isArray(nextPayload)) {
        if (phaseData) phaseData.uiUxFlow = nextPayload
        if (window.__BUILDERX_PHASES__) window.__BUILDERX_PHASES__.uiUxFlow = nextPayload
        window.dispatchEvent(new CustomEvent(uiUxFlowPayloadUpdatedEvent))
      }
      setNoteChatSendStatus('Codex Chat text polish completed and validated changes were applied.')
    } catch (error) {
      const message = error instanceof Error ? error.message : 'The text polish request could not be completed in Codex Chat.'
      window.alert(message)
      setNoteChatSendStatus(message)
    } finally {
      setUiUxBatchPolishBusy(false)
      setUiUxFlowAiBusy(false)
    }
  }

  async function processUiUxFlowAiChatQueue() {
    if (uiUxFlowAiChatQueueProcessingRef.current) return
    uiUxFlowAiChatQueueProcessingRef.current = true

    try {
      while (uiUxFlowAiChatQueueRef.current.length > 0) {
        const item = uiUxFlowAiChatQueueRef.current[0]
        setUiUxFlowAiChatQueue((current) => current.map((message) => phaseField(message, 'id') === phaseField(item, 'id') ? { ...message, status: 'processing' } : message))
        const success = await submitUiUxFlowAiPlanRequest('respond_ui_ux_flow_ai_plan', phaseField(item, 'message'), item, false)
        uiUxFlowAiChatQueueRef.current = uiUxFlowAiChatQueueRef.current.slice(1)
        setUiUxFlowAiChatQueue((current) => success
          ? current.filter((message) => phaseField(message, 'id') !== phaseField(item, 'id'))
          : current.map((message) => phaseField(message, 'id') === phaseField(item, 'id') ? { ...message, status: 'failed' } : message))
      }
    } finally {
      uiUxFlowAiChatQueueProcessingRef.current = false
    }
  }

  function enqueueUiUxFlowAiChatMessage() {
    const message = uiUxFlowAiChatMessage.trim()
    if ((message === '' && uiUxFlowAiChatAttachments.length === 0) || uiUxFlowAiFocusScope === 'flow') return
    const context = uiUxFlowAiCurrentFocusContext()
    const item = {
      ...context,
      id: `flow-ai-chat-${Date.now()}-${Math.random().toString(16).slice(2)}`,
      role: 'user',
      message: message !== '' ? message : 'Review the attached screenshot.',
      status: 'queued',
      createdAt: 'Queued',
      chat_attachment_files: uiUxFlowAiChatAttachments,
      image_attachments: uiUxFlowAiChatAttachments.map((file) => ({
        original_name: file.name,
        mime_type: file.type,
        file_size: file.size,
        preview_url: URL.createObjectURL(file),
      })),
    }
    uiUxFlowAiChatQueueRef.current = [...uiUxFlowAiChatQueueRef.current, item]
    setUiUxFlowAiChatQueue((current) => [...current, item])
    setUiUxFlowAiChatMessage('')
    setUiUxFlowAiChatAttachments([])
    void processUiUxFlowAiChatQueue()
  }

  async function runUiUxFlowBuilderCodex(builderPromptOverride = '', snapshotOverride?: Record<string, any>) {
    if (uiUxFlowBuilderBusy) return
    const snapshot = snapshotOverride || uiUxFlowSnapshot()
    const builderPrompt = builderPromptOverride || buildUiUxFlowMemoryPackPrompt()
    const formData = new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', 'run_ui_ux_flow_builder_codex')
    formData.set('ui_ux_flow', flowKey)
    formData.set('ui_ux_section', sectionKey)
    formData.set('ui_ux_snapshot', JSON.stringify(snapshot))
    formData.set('builder_prompt', builderPrompt)
    formData.set('builder_action_mode', phaseField(snapshot.builderx_action, 'mutation_mode'))
    formData.set('builder_execution_mode', phaseField(snapshot.builderx_action, 'execution_mode'))
    formData.set('ai_memory_profile', phaseField(snapshot.builderx_action, 'execution_mode') === 'plan_only' ? 'compact' : '')
    formData.set('phase_key', phaseField(snapshot, 'phase_key'))
    formData.set('task_key', phaseField(snapshot, 'task_key'))
    formData.set('note_key', phaseField(snapshot, 'note_key'))

    setUiUxFlowBuilderConfirmOpen(false)
    setUiUxFlowBuilderBusy(true)
    setUiUxFlowBuilderResult(null)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return
      }
      const result = JSON.parse(rawText)
      if (maybeHandleAiBackgroundJobResult(result)) {
        return
      }
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'UI - UX Flow Builder failed.')
        return
      }
      const nextResult = result.data?.ui_ux_flow_builder_result || {}
      setUiUxFlowBuilderResult(nextResult)
      if (phaseData) {
        phaseData.uiUxFlowBuilderResult = nextResult
      }
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'UI - UX Flow Builder failed.')
    } finally {
      setUiUxFlowBuilderBusy(false)
    }
  }

