  function svgPointerPoint(event: React.PointerEvent<SVGSVGElement | SVGGElement>) {
    const svg = svgRef.current
    if (!svg) return { x: 0, y: 0 }

    const rect = svg.getBoundingClientRect()

    return {
      x: ((event.clientX - rect.left) / rect.width) * canvasWidth,
      y: ((event.clientY - rect.top) / rect.height) * canvasHeight,
    }
  }

  function handleCanvasItemPointerDown(
    event: React.PointerEvent<SVGGElement>,
    itemKey: string,
    position: ProjectFlowNodePosition,
    linked: Array<{ key: string; position: ProjectFlowNodePosition }> = [],
  ) {
    event.preventDefault()
    event.stopPropagation()
    uiUxDragMovedRef.current = false
    const point = svgPointerPoint(event)
    dragRef.current = {
      itemKey,
      offsetX: point.x - position.x,
      offsetY: point.y - position.y,
      originX: position.x,
      originY: position.y,
      linked,
    }
    event.currentTarget.setPointerCapture(event.pointerId)
  }

  type UiUxNoteLayout = {
    id: string
    position: ProjectFlowNodePosition
    noteHolder: { id: string; position: ProjectFlowNodePosition }
    databaseLayout?: { id: string; position: ProjectFlowNodePosition } | null
    formLayout?: { id: string; position: ProjectFlowNodePosition } | null
    formLayouts?: Array<{ id: string; formId: string; form: Record<string, any>; position: ProjectFlowNodePosition }>
  }

  function linkedSubphasePositions(subphaseLayouts: Array<{
    id: string
    position: ProjectFlowNodePosition
    noteLayouts: Array<UiUxNoteLayout>
  }>) {
    return subphaseLayouts.flatMap((subphaseLayout) => [
      { key: subphaseLayout.id, position: subphaseLayout.position },
      ...subphaseLayout.noteLayouts.map((noteLayout) => ({ key: noteLayout.id, position: noteLayout.position })),
      ...subphaseLayout.noteLayouts.map((noteLayout) => ({ key: noteLayout.noteHolder.id, position: noteLayout.noteHolder.position })),
      ...subphaseLayout.noteLayouts.flatMap((noteLayout) => noteLayout.databaseLayout ? [{ key: noteLayout.databaseLayout.id, position: noteLayout.databaseLayout.position }] : []),
      ...subphaseLayout.noteLayouts.flatMap((noteLayout) => (noteLayout.formLayouts || (noteLayout.formLayout ? [noteLayout.formLayout] : [])).map((formLayout) => ({ key: formLayout.id, position: formLayout.position }))),
    ])
  }

  function linkedNotePositions(noteLayouts: Array<UiUxNoteLayout>) {
    return noteLayouts.flatMap((noteLayout) => [
      { key: noteLayout.id, position: noteLayout.position },
      { key: noteLayout.noteHolder.id, position: noteLayout.noteHolder.position },
      ...(noteLayout.databaseLayout ? [{ key: noteLayout.databaseLayout.id, position: noteLayout.databaseLayout.position }] : []),
      ...(noteLayout.formLayouts || (noteLayout.formLayout ? [noteLayout.formLayout] : [])).map((formLayout) => ({ key: formLayout.id, position: formLayout.position })),
    ])
  }

