  function handleSvgPointerMove(event: React.PointerEvent<SVGSVGElement>) {
    const drag = dragRef.current
    if (!drag) return

    const point = svgPointerPoint(event)
    const nextX = Math.max(0, point.x - drag.offsetX)
    const nextY = Math.max(0, point.y - drag.offsetY)
    const deltaX = nextX - drag.originX
    const deltaY = nextY - drag.originY
    if (Math.abs(deltaX) > 3 || Math.abs(deltaY) > 3) {
      uiUxDragMovedRef.current = true
    }

    setPositions((current) => {
      const nextPositions = {
        ...current,
        [drag.itemKey]: { x: Math.round(nextX), y: Math.round(nextY) },
      }

      drag.linked.forEach((linkedItem) => {
        nextPositions[linkedItem.key] = {
          x: Math.max(0, Math.round(linkedItem.position.x + deltaX)),
          y: Math.max(0, Math.round(linkedItem.position.y + deltaY)),
        }
      })

      return nextPositions
    })
  }

  function handleSvgPointerUp() {
    dragRef.current = null
  }

