  function applyNoteReviewResult(note: Record<string, any>, resultData: Record<string, any>, openModal = true) {
    const noteKey = phaseField(resultData, 'note_key', phaseField(note, 'noteKey'))
    const noteChatConsolidated = resultData.note_chat_consolidated === true
      || phaseField(resultData, 'note_chat_consolidated') === '1'
      || phaseField(resultData, 'note_chat_consolidated') === 'true'
      || note.noteChatConsolidated === true
      || phaseField(note, 'noteChatConsolidated') === '1'
      || phaseField(note, 'noteChatConsolidated') === 'true'
    const nextNote = {
      ...note,
      reviewStatus: phaseField(resultData, 'review_status', phaseField(note, 'reviewStatus', 'UNREVIEWED')),
      reviewPayload: resultData?.review_payload || note.reviewPayload || {},
      reviewChat: Array.isArray(resultData?.review_chat) ? resultData.review_chat : note.reviewChat || [],
      attachments: Array.isArray(resultData?.attachments) ? resultData.attachments : note.attachments || [],
      refinedText: phaseField(resultData, 'note_text_refined', phaseField(note, 'refinedText')),
      noteChatConsolidated,
    }
    if (noteKey !== '') {
      setReviewOverrides((current) => ({
        ...current,
        [noteKey]: {
          reviewStatus: nextNote.reviewStatus,
          reviewPayload: nextNote.reviewPayload,
          reviewChat: nextNote.reviewChat,
          attachments: nextNote.attachments,
          refinedText: nextNote.refinedText,
          noteChatConsolidated: nextNote.noteChatConsolidated,
        },
      }))
    }
    if (openModal) openReviewModal(nextNote)
  }

  async function runNoteReviewAction(action: 'review_note_codex' | 'respond_note_review' | 'consolidate_note_review', note: Record<string, any>, extra: Record<string, string> = {}, sourceForm?: HTMLFormElement, openModal = true, imageAttachments: File[] = []): Promise<boolean> {
    const noteKey = phaseField(note, 'noteKey')
    if (noteKey === '' || reviewBusyNoteKey !== '') return false

    const formData = sourceForm ? new FormData(sourceForm) : new FormData()
    formData.set('csrf', phaseData?.csrf || '')
    formData.set('action', action)
    formData.set('note_key', noteKey)
    Object.entries(extra).forEach(([key, value]) => formData.set(key, value))
    imageAttachments.forEach((file) => formData.append('images[]', file))

    setReviewBusyNoteKey(noteKey)
    try {
      const response = await fetch('./', {
        method: 'POST',
        body: formData,
        headers: { 'X-Requested-With': 'XMLHttpRequest', Accept: 'application/json' },
      })
      const contentType = response.headers.get('content-type') || ''
      const rawText = await response.text()
      if (!contentType.includes('application/json')) {
        window.alert(`Action returned HTML instead of JSON. HTTP ${response.status}. Please refresh and try again.`)
        return false
      }
      const result = JSON.parse(rawText)
      if (maybeHandleAiBackgroundJobResult(result)) {
        return true
      }
      if (!(result.ok || result.success)) {
        window.alert(result.message || 'Codex Chat note review failed.')
        return false
      }
      applyNoteReviewResult(note, result.data || {}, openModal)
      setReviewMessage('')
      return true
    } catch (error) {
      window.alert(error instanceof Error ? error.message : 'Codex Chat note review failed.')
      return false
    } finally {
      setReviewBusyNoteKey('')
    }
  }

