	                        <label key={fieldName} className="flex items-center gap-2 rounded-md border bg-background p-2 text-[11px]">
	                          <input type="checkbox" checked={formWorkflowConfig.output_fields?.includes(fieldName)} onChange={() => toggleFormWorkflowField('output_fields', fieldName)} />
	                          <span>{phaseField(field, 'label', fieldName)}</span>
	                        </label>
