type VisualAnnotationPoint = { x: number; y: number }
type VisualAnnotationRect = { x: number; y: number; width: number; height: number }
type VisualAnnotationMode = 'idle' | 'select' | 'pen' | 'circle' | 'rectangle' | 'arrow'
type VisualCodexTarget = 'local' | 'vscode'
type NoteChatDeliveryStatus = 'saved' | 'queued' | 'sending' | 'processing' | 'sent' | 'completed' | 'failed'
type NoteChatQueueItem = {
  id: string
  noteKey: string
  note: Record<string, any>
  message: string
  attachments: File[]
  target: VisualCodexTarget
  purpose: 'message' | 'consolidation'
  persisted: boolean
  status: NoteChatDeliveryStatus
  createdAt: string
  error: string
}
type VisualAnnotationMark = {
  id: string
  kind: Exclude<VisualAnnotationMode, 'idle' | 'select'>
  start: VisualAnnotationPoint
  end: VisualAnnotationPoint
  points: VisualAnnotationPoint[]
}
type VisualAnnotationTarget = {
  selector: string
  tag: string
  label: string
  ariaLabel: string
  text: string
  rect: VisualAnnotationRect
  elementId: string
  className: string
  attributes: Record<string, string>
  computedStyles: Record<string, string>
  outerHtml: string
  parentOuterHtml: string
}
type SharinganAttachment = {
  id: string
  name: string
  mimeType: string
  size: number
  dataUrl: string
}

