  const [, setUiUxFlowRefreshTick] = React.useState(0)

  React.useEffect(() => {
    applyAdminTheme(theme)
    writeStoredPhaseTheme(theme)
  }, [theme])

  React.useEffect(() => {
    function handleUiUxFlowPayloadUpdated() {
      setUiUxFlowRefreshTick((current) => current + 1)
    }

    window.addEventListener(uiUxFlowPayloadUpdatedEvent, handleUiUxFlowPayloadUpdated)

    return () => window.removeEventListener(uiUxFlowPayloadUpdatedEvent, handleUiUxFlowPayloadUpdated)
  }, [])

  const handleThemeToggle = React.useCallback(() => {
    setTheme((currentTheme) => currentTheme === 'dark' ? 'light' : 'dark')
  }, [])

  const activeView = phaseData?.activeView ?? 'phases'
