  const readBridgeEventStream = async (url: string, onEvent: (name: string, data: Record<string, any>) => boolean): Promise<void> => {
    const response = await fetch(url, { cache: 'no-store', headers: { Accept: 'text/event-stream' } })
    if (!response.ok || !response.body) throw new Error('The BuilderX bridge progress stream is unavailable.')
    const reader = response.body.getReader()
    const decoder = new TextDecoder()
    let buffer = ''
    let terminal = false
    const dispatch = (block: string) => {
      let name = 'message'
      const dataLines: string[] = []
      for (const line of block.split('\n')) {
        if (line.startsWith('event:')) name = line.slice(6).trim()
        if (line.startsWith('data:')) dataLines.push(line.slice(5).trim())
      }
      if (!dataLines.length) return
      let data: Record<string, any>
      try {
        data = JSON.parse(dataLines.join('\n'))
      } catch {
        throw new Error('The BuilderX bridge returned invalid progress data.')
      }
      terminal = onEvent(name, data)
    }
    while (!terminal) {
      const { done, value } = await reader.read()
      buffer += decoder.decode(value, { stream: !done }).replace(/\r\n/g, '\n')
      let separator = buffer.indexOf('\n\n')
      while (separator >= 0) {
        const block = buffer.slice(0, separator)
        buffer = buffer.slice(separator + 2)
        dispatch(block)
        if (terminal) break
        separator = buffer.indexOf('\n\n')
      }
      if (done) break
    }
    await reader.cancel().catch(() => {})
    if (!terminal) throw new Error('The BuilderX bridge progress stream ended before completion.')
  }
