      addRequirementsEvent('Requirements Analysis transaction committed and post-commit read-back passed.', 'complete')
      setRequirementsWorkflow((current) => ({ ...current, status: 'success', step: 'complete', message: 'Requirements Analysis completed through nine persisted chunks, deterministic merge, integration review, and verified persistence.', report: JSON.stringify({ run_key: runKey, engine_type: run?.engine_type, workflow_key: run?.workflow_key, status: run?.status, semantic_chunks: 9, contract_hash: persistence.contractHash, analysis_key: persistence.analysisKey, persistence: persistence.status, read_back_verified: persistence.readBackVerified }, null, 2), error: '', events: settleOneFlowEvents(appendOneFlowEvent(current.events, 'Persistent Requirements Analysis workflow completed.', 'complete'), 'complete') }))
